        "everyday|4:1|0|w0": "قائمة الطعام",
        "everyday|4:1|0|w1": "نادل",
        "everyday|4:1|0|w2": "مقبلات",
        "everyday|4:1|0|w3": "الطبق الرئيسي",
        "everyday|4:1|0|w4": "حلوى",
        "everyday|4:1|0|w5": "منديل",
        "everyday|4:1|1|p0": "لو سمحت، هل يمكن أن تحضر لنا قائمة الطعام وبعض الماء؟",
        "everyday|4:1|1|p1": "نصحنا النادل بالنير دوسا، فطلبنا طبقين.",
        "everyday|4:1|1|p2": "هل نتشارك طبقا من المقبلات ثم يطلب كل منا طبقه الرئيسي؟",
        "everyday|4:1|1|p3": "أنا شبعان جدا ولا أستطيع أكل الحلوى، لكنني أود فنجان قهوة فلتر.",
        "everyday|4:1|1|p4": "هل يمكنك أن تحضر لنا بعض المناديل الإضافية وملعقة صغيرة لابني؟",
        "everyday|4:1|2|w0": "مكوّن",
        "everyday|4:1|2|w1": "نباتي",
        "everyday|4:1|2|w2": "حار",
