        "everyday|4:1|2|w4": "بقشيش",
        "everyday|4:1|2|w5": "حصة",
        "everyday|4:1|3|p0": "لدي حساسية من المكسرات، فهل يمكنك التحقق من مكونات هذا الكاري؟",
        "everyday|4:1|3|p1": "كلنا نباتيون، فمن فضلك تأكد من عدم وجود بيض في أي شيء.",
        "everyday|4:1|3|p2": "هل يمكنك أن تجعله أقل حرارة؟ ابني لا يتحمل الكثير من الفلفل الحار.",
        "everyday|4:1|3|p3": "الحصص هنا كبيرة جدا، فهل يمكنك أن تغلف الباقي لنأخذه معنا؟",
        "everyday|4:1|3|p4": "الفاتورة تشمل رسوم الخدمة أصلا، فلا داعي لأن نترك بقشيشا.",
        "everyday|4:1|4|title": "عشاء عيد ميلاد في أودوبي",
        "everyday|4:1|4|text": "بمناسبة عيد ميلاد جدته الثمانين، حجز كيران طاولة في مطعم مشهور في أودوبي. أحضر النادل قائمة الطعام واقترح البانير تيكا كطبق مقبلات. وابنة عم كيران، نيشا، لديها حساسية من الفول السوداني، لذلك طلب كيران من النادل أن يتحقق من كل طبق بعناية. أرادت جدته أن يكون طبقها الرئيسي أقل حرارة، فوافق الطباخ بكل سرور. وللحلوى، تشاركت العائلة كلها كأس آيس كريم غدباد ضخما. وعندما وصلت الفاتورة، لاحظ كيران أن رسوم خدمة بنسبة خمسة في المئة مضافة إليها بالفعل. ومع ذلك ترك بقشيشا صغيرا، لأن النادل كان صبورا جدا معهم. وأخذوا ما تبقى من خبز الروتي معهم إلى البيت.",
        "everyday|4:1|4|q0": "لماذا طلب كيران من النادل أن يتحقق من كل طبق؟",
        "everyday|4:1|4|q0o0": "لأن ابنة عمه لديها حساسية من الفول السوداني",
        "everyday|4:1|4|q0o1": "لأن جدته نباتية",
        "everyday|4:1|4|q0o2": "لأن الطعام كان باردا",
        "everyday|4:1|4|q0o3": "لأن قائمة الطعام بلا أسعار",
        "everyday|4:1|4|q1": "ماذا تشاركت العائلة كحلوى؟",
        "everyday|4:1|4|q1o0": "آيس كريم غدباد",
