        "everyday|4:1|4|q2o2": "لأنه لم تكن هناك رسوم خدمة",
        "everyday|4:1|4|q2o3": "لأن جدته طلبت منه ذلك",
        "everyday|4:1|5|title": "طلب العشاء",
        "everyday|4:1|5|scenario": "أنانيا وصديقتها في مطعم في بونه. يأتي النادل مانوج ليأخذ طلبهما.",
        "everyday|4:1|5|l0": "مساء الخير يا سيدتي. هل أنتما مستعدتان للطلب، أم تحتاجان إلى بضع دقائق أخرى؟",
        "everyday|4:1|5|l1": "أظن أننا مستعدتان. ما طبق اليوم؟",
        "everyday|4:1|5|l2": "لدينا اليوم كاري سمك مالفاني وثالي نباتي.",
        "everyday|4:1|5|l3": "طبق ثالي واحد لصديقتي من فضلك. هل كاري السمك حار جدا؟",
        "everyday|4:1|5|l4": "إنه حار نوعا ما، لكن الطاهي يستطيع أن يجعله أخف إذا أردت.",
        "everyday|4:1|5|l5": "نعم، اجعله خفيفا من فضلك. وأيضا صديقتي لديها حساسية من المكسرات، فلا تضعوا الكاجو في الثالي.",
        "everyday|4:1|5|l6": "بالطبع، سأخبر المطبخ. هل تريدان شيئا للشرب؟",
        "everyday|4:1|5|l7": "كوبان من اللاسي الحلو من فضلك. وهل يمكننا الدفع عبر يو بي آي في النهاية؟",
        "everyday|4:1|5|l8": "بالتأكيد، نقبل يو بي آي والبطاقات. سأعود بمشروباتكما بعد قليل.",
        "everyday|4:1|5|l9": "شكرا، هذا لطف كبير منك.",
        "everyday|4:1|5|q0": "ما أطباق اليوم الخاصة؟",
        "everyday|4:1|5|q0o0": "كاري سمك مالفاني وثالي نباتي",
