        "everyday|5:1|0|w5": "بهو الفندق",
        "everyday|5:1|1|p0": "أود أن أحجز لليلتين ابتداء من الخامس من مارس.",
        "everyday|5:1|1|p1": "هل يمكنك أن تتحقق من توفر غرفة مزدوجة في عطلة نهاية هذا الأسبوع؟",
        "everyday|5:1|1|p2": "تسجيل الدخول عند الظهر، لكن يمكنك أن تترك حقائبك عندنا قبل ذلك.",
        "everyday|5:1|1|p3": "هل يمكن تأخير موعد المغادرة؟ قطارنا ينطلق في الساعة السادسة.",
        "everyday|5:1|1|p4": "سائق التاكسي ينتظرك في بهو الفندق.",
