        "everyday|5:1|2|w5": "خدمة الغرف",
        "everyday|5:1|3|p0": "هل يمكنكم إرسال منشفتين نظيفتين ووسادة إضافية من فضلكم؟",
        "everyday|5:1|3|p1": "للأسف، مكيف الهواء في الغرفة 204 لا يعمل أبدا.",
        "everyday|5:1|3|p2": "لم تنظف خدمة التنظيف غرفتنا بعد، والساعة الآن الثالثة.",
        "everyday|5:1|3|p3": "لا أريد أن أقدم شكوى، لكن الغرفة صاخبة جدا.",
        "everyday|5:1|3|p4": "هل خدمة الغرف متاحة بعد الحادية عشرة، أم يكون المطبخ قد أغلق؟",
        "everyday|5:1|4|title": "ليلة صاخبة في ماديكيري",
        "everyday|5:1|4|text": "حجز نيخيل وزوجته شريا في فندق صغير في ماديكيري لقضاء عطلة نهاية أسبوع طويلة. وعند تسجيل الدخول، أعطتهما موظفة الاستقبال غرفة مزدوجة في الطابق الأرضي. وفي تلك الليلة، أصدر مكيف الهواء صوت خشخشة عاليا، وكانت الغرفة دافئة جدا فلم يستطيعا النوم. اتصل نيخيل بمكتب الاستقبال وقدم شكوى بأدب. فاعتذر المدير ونقلهما إلى غرفة أهدأ في الطابق العلوي تطل على التلال. وفي صباح اليوم التالي، أحضرت خدمة التنظيف مناشف نظيفة ووسائد إضافية دون أن يطلبا ذلك. وعند تسجيل المغادرة، عرض عليهما المدير فطورا مجانيا تعويضا عن الإزعاج.",
        "everyday|5:1|4|q0": "ما المشكلة في الغرفة الأولى؟",
        "everyday|5:1|4|q0o0": "كان مكيف الهواء صاخبا",
        "everyday|5:1|4|q0o1": "لم تكن فيها مناشف",
        "everyday|5:1|4|q0o2": "كان السرير مكسورا",
        "everyday|5:1|4|q0o3": "كان الباب لا يُقفل",
        "everyday|5:1|4|q1": "ماذا فعل المدير بشأن الشكوى؟",
        "everyday|5:1|4|q1o0": "نقلهما إلى غرفة أهدأ",
        "everyday|5:1|4|q1o1": "أعاد لهما المبلغ كاملا",
        "everyday|5:1|4|q1o2": "طلب منهما المغادرة",
        "everyday|5:1|4|q1o3": "أرسل فنيا في الأسبوع التالي",
        "everyday|5:1|4|q2": "ماذا حصلا عليه عند تسجيل المغادرة؟",
        "everyday|5:1|4|q2o0": "فطور مجاني",
        "everyday|5:1|4|q2o1": "توصيلة تاكسي مجانية",
        "everyday|5:1|4|q2o2": "علبة قهوة مطحونة",
        "everyday|5:1|4|q2o3": "تأخير موعد المغادرة",
        "everyday|5:1|5|title": "تسجيل الدخول",
        "everyday|5:1|5|scenario": "يصل راهول إلى فندق في هوبالي في المساء، وتسجل له فرح دخوله في مكتب الاستقبال.",
        "everyday|5:1|5|l0": "مساء الخير يا سيدي، ومرحبا بك في فندق سنغم. هل لديك حجز لدينا؟",
        "everyday|5:1|5|l1": "نعم، الحجز باسم راهول جوشي، لثلاث ليال.",
        "everyday|5:1|5|l2": "نعم، أراه أمامي: غرفة مزدوجة حتى يوم الجمعة. هل يمكنني أن أرى بطاقة هوية بها صورة من فضلك؟",
        "everyday|5:1|5|l3": "تفضلي، هذه بطاقة آدهار الخاصة بي. هل الفطور مشمول في السعر؟",
        "everyday|5:1|5|l4": "نعم. يقدم الفطور في المطعم من السابعة حتى العاشرة.",
        "everyday|5:1|5|l5": "رائع. هل يمكن أن تكون غرفتي بعيدة عن المصعد؟ نومي خفيف.",
        "everyday|5:1|5|l6": "بالطبع. سأعطيك الغرفة 312، في الطرف الهادئ من الممر.",
        "everyday|5:1|5|l7": "شكرا. وفي أي ساعة يكون تسجيل المغادرة يوم الجمعة؟",
        "everyday|5:1|5|l8": "تسجيل المغادرة في الحادية عشرة، لكن أخبرنا إذا احتجت إلى بعض الوقت الإضافي.",
        "everyday|5:1|5|l9": "هذا مفيد جدا. شكرا جزيلا.",
