        "everyday|6:1|2|w5": "حمّال",
        "everyday|6:1|3|p0": "هناك تأخير لمدة أربع ساعات بسبب الضباب الكثيف قرب دلهي.",
        "everyday|6:1|3|p1": "إذا ألغيت قبل أكثر من يومين، تكون رسوم الإلغاء قليلة.",
        "everyday|6:1|3|p2": "ألغيت الحافلة، فذهبت إلى شباك الاستفسارات لأطلب استرداد المبلغ.",
        "everyday|6:1|3|p3": "هل سمعت ذلك الإعلان؟ علينا أن نحمل أمتعتنا إلى الرصيف رقم خمسة.",
        "everyday|6:1|3|p4": "حسب جدول المواعيد، تنطلق آخر حافلة إلى ميسورو في العاشرة.",
        "everyday|6:1|4|title": "في الوقت المناسب تماما",
        "everyday|6:1|4|text": "كانت آشا مسافرة من هوبالي إلى بونه لحضور زفاف أختها. وكانت قد حجزت مقعدها قبل شهرين، ولديها سرير سفلي في العربة إس 4. وفي المحطة، قال إعلان إن هناك تأخيرا لمدة ثلاث ساعات. فتحققت آشا من جدول مواعيد الحافلات على هاتفها، ووجدت حافلة تصل إلى بونه أسرع. ألغت تذكرة القطار عبر الإنترنت، فوصل المبلغ المسترد إلى حسابها خلال يومين. وحمل حمال حقائبها الثقيلة إلى موقف الحافلات مقابل أجر بسيط. ووصلت آشا إلى بونه في الوقت المناسب تماما لحفل الحناء.",
        "everyday|6:1|4|q0": "لماذا كانت آشا ذاهبة إلى بونه؟",
        "everyday|6:1|4|q0o0": "لحضور زفاف أختها",
