        "everyday|6:1|4|q2o3": "بسيارة أجرة",
        "everyday|6:1|5|title": "قطار ملغى",
        "everyday|6:1|5|scenario": "في محطة قطارات ميسورو، تكتشف كافيتا أن قطارها إلى بنغالورو قد ألغي، فتطلب المساعدة من سوريش في شباك الاستفسارات.",
        "everyday|6:1|5|l0": "لو سمحت، سمعت للتو إعلانا يقول إن قطار تشاموندي السريع قد ألغي. هل هذا صحيح؟",
        "everyday|6:1|5|l1": "للأسف نعم يا سيدتي. هناك مشكلة في السكة قرب مانديا.",
        "everyday|6:1|5|l2": "أوه، لا! لدي اجتماع مهم في بنغالورو في الساعة الثانية. ما الخيارات المتاحة لي؟",
        "everyday|6:1|5|l3": "هناك قطار سريع في الحادية عشرة والربع من الرصيف رقم ثلاثة. يصل عادة في الواحدة والنصف.",
        "everyday|6:1|5|l4": "هل بقيت فيه أي مقاعد؟",
        "everyday|6:1|5|l5": "في العربة العامة فقط للأسف. أما المقاعد المحجوزة فكلها على قائمة الانتظار.",
        "everyday|6:1|5|l6": "العربة العامة لا بأس بها. وماذا سيحدث لتذكرتي الملغاة؟",
        "everyday|6:1|5|l7": "بما أن السكك الحديدية هي التي ألغت القطار، فستستردين المبلغ كاملا خلال أسبوع.",
        "everyday|6:1|5|l8": "هل أحتاج إلى ملء استمارة لاسترداد المبلغ؟",
        "everyday|6:1|5|l9": "لا يا سيدتي. يتم ذلك تلقائيا، لأنك حجزت عبر الإنترنت. رحلة آمنة.",
        "everyday|6:1|5|q0": "لماذا ألغي قطار تشاموندي السريع؟",
        "everyday|6:1|5|q0o0": "مشكلة في السكة قرب مانديا",
