        "services|1:1|0|w0": "صيدلية",
        "services|1:1|0|w1": "صيدلي",
        "services|1:1|0|w2": "قرص",
        "services|1:1|0|w3": "شراب دواء",
        "services|1:1|0|w4": "جرعة",
        "services|1:1|0|w5": "أثر جانبي",
        "services|1:1|1|p0": "هل توجد صيدلية قريبة تبقى مفتوحة طوال الليل؟",
        "services|1:1|1|p1": "هل يمكنك أن تخبرني بالجرعة المناسبة لطفل عمره عشر سنوات؟",
        "services|1:1|1|p2": "قال الصيدلي إن عليّ أن أتناول قرصا واحدا بعد كل وجبة.",
        "services|1:1|1|p3": "هل لشراب السعال هذا أي آثار جانبية، مثل النعاس؟",
        "services|1:1|1|p4": "آسف، لا يمكننا أن نعطيك هذه الأقراص بدون وصفة طبية.",
        "services|1:1|2|w0": "مرهم",
        "services|1:1|2|w1": "حساسية",
        "services|1:1|2|w2": "تاريخ انتهاء الصلاحية",
        "services|1:1|2|w3": "مسكّن ألم",
        "services|1:1|2|w4": "مضاد حيوي",
        "services|1:1|2|w5": "نعسان",
        "services|1:1|3|p0": "ادهن الحرق بهذا المرهم بلطف مرتين في اليوم.",
        "services|1:1|3|p1": "لدي حساسية من البنسلين، فمن فضلك اقترح شيئا آخر.",
        "services|1:1|3|p2": "تحقق دائما من تاريخ انتهاء الصلاحية قبل أن تفتح شريطا جديدا.",
        "services|1:1|3|p3": "أكمل علاج المضاد الحيوي كاملا، حتى لو شعرت بتحسن.",
        "services|1:1|3|p4": "قد يجعلك مسكن الألم هذا نعسانا، فلا تقد السيارة بعد تناوله.",
        "services|1:1|4|title": "في الصيدلية في وقت متأخر من الليل",
        "services|1:1|4|text": "في الساعة العاشرة من إحدى الليالي في ميسورو، استيقظ روهان، أخو ميرا الصغير، وهو يعاني من حمى شديدة. كانت طبيبة العائلة خارج المدينة، فاتصلت بها ميرا لتطلب نصيحتها. قالت الطبيبة إن شرابا خافضا للحرارة يكفي حتى الصباح. ووجدت ميرا صيدلية قرب موقف الحافلات تبقى مفتوحة طوال الليل. أخبرت الصيدلي أن روهان عمره ثماني سنوات وأن لديه حساسية من أحد المضادات الحيوية. فتحقق الصيدلي من تاريخ انتهاء الصلاحية، وكتب الجرعة على العلبة، وحذرها من أن الشراب قد يجعل روهان نعسانا. وفي الصباح، كانت حرارة روهان قد انخفضت وصار يطلب الدوسا.",
        "services|1:1|4|q0": "لماذا ذهبت ميرا إلى الصيدلية ليلا؟",
        "services|1:1|4|q0o0": "كانت حرارة روهان مرتفعة جدا",
        "services|1:1|4|q0o1": "كانت تحتاج إلى شاحن هاتف جديد",
        "services|1:1|4|q0o2": "حرق روهان يده",
        "services|1:1|4|q0o3": "طلبت منها الطبيبة شراء فيتامينات",
        "services|1:1|4|q1": "ماذا كتب الصيدلي على العلبة؟",
        "services|1:1|4|q1o0": "الجرعة",
        "services|1:1|4|q1o1": "السعر",
        "services|1:1|4|q1o2": "اسم روهان",
        "services|1:1|4|q1o3": "رقم هاتف الطبيبة",
        "services|1:1|4|q2": "كيف كان روهان في الصباح؟",
        "services|1:1|4|q2o0": "كانت حرارته قد انخفضت",
        "services|1:1|4|q2o1": "اضطر إلى الذهاب إلى المستشفى",
