        "services|1:1|5|title": "سؤال الصيدلانية",
        "services|1:1|5|scenario": "كيران مصاب بزكام شديد، فيطلب النصيحة من لاتا، وهي صيدلانية في هوبالي.",
        "services|1:1|5|l0": "مساء الخير. كيف يمكنني مساعدتك؟",
        "services|1:1|5|l1": "مرحبا. أنفي مسدود وحلقي يؤلمني منذ أمس. هل يمكنك أن تقترحي شيئا؟",
        "services|1:1|5|l2": "هل عندك حمى، أو حساسية من أي دواء؟",
        "services|1:1|5|l3": "لا حمى، ولا حساسية على حد علمي. وأفضل ألا آخذ شيئا قويا جدا.",
        "services|1:1|5|l4": "إذن خذ هذه الأقراص للزكام، واحدا في الصباح وواحدا في الليل، بعد الأكل.",
        "services|1:1|5|l5": "هل هناك أي آثار جانبية يجب أن أعرفها؟",
        "services|1:1|5|l6": "قد تجعلك نعسانا قليلا، فمن فضلك لا تقد السيارة بعد جرعة الليل.",
        "services|1:1|5|l7": "فهمت. وهل هناك شيء للحلق أيضا؟",
        "services|1:1|5|l8": "هذا الشراب سيفيدك: ملعقتان، ثلاث مرات في اليوم. وإذا لم تتحسن خلال ثلاثة أيام، فمن فضلك راجع طبيبا.",
        "services|1:1|5|l9": "هذا مفيد جدا، شكرا. هل يمكنني الدفع عبر يو بي آي؟",
        "services|1:1|5|q0": "كم مرة يجب أن يتناول كيران الأقراص؟",
        "services|1:1|5|q0o0": "مرتين في اليوم، بعد الأكل",
        "services|1:1|5|q0o1": "مرة في الأسبوع",
        "services|1:1|5|q0o2": "كل ساعة",
        "services|1:1|5|q0o3": "فقط عندما تكون عنده حمى",
        "services|1:1|5|q1": "من أي أثر جانبي حذرته لاتا؟",
        "services|1:1|5|q1o0": "الشعور بالنعاس",
        "services|1:1|5|q1o1": "طفح جلدي",
        "services|1:1|5|q1o2": "فقدان الشهية",
        "services|1:1|5|q1o3": "صداع",
        "services|1:1|5|q2": "ماذا يجب أن يفعل كيران إذا لم يتحسن خلال ثلاثة أيام؟",
