        "services|2:1|0|w3": "فرقة الإطفاء",
        "services|2:1|0|w4": "حادث",
        "services|2:1|0|w5": "معلم بارز",
        "services|2:1|1|p0": "أريد أن أبلغ عن حادث سير قرب موقف حافلات هوبالي.",
        "services|2:1|1|p1": "أرسلوا سيارة إسعاف بسرعة من فضلكم، هناك رجل ملقى على الطريق.",
        "services|2:1|1|p2": "في حالة الطوارئ، اتصل بخط المساعدة 112 وتحدث ببطء ووضوح.",
        "services|2:1|1|p3": "فرقة الإطفاء في الطريق، فمن فضلكم اخرجوا من المبنى الآن.",
        "services|2:1|1|p4": "أقرب معلم هو المعبد الكبير المقابل لمحطة البنزين.",
        "services|2:1|2|w0": "مصاب",
        "services|2:1|2|w1": "فاقد الوعي",
        "services|2:1|2|w2": "نزيف",
        "services|2:1|2|w3": "إسعافات أولية",
        "services|2:1|2|w4": "سرقة",
        "services|2:1|2|w5": "ذعر",
        "services|2:1|3|p0": "هناك شخصان مصابان، وأحدهما فاقد الوعي.",
        "services|2:1|3|p1": "اضغط بقطعة قماش نظيفة على الجرح لإيقاف النزيف.",
        "services|2:1|3|p2": "هل تعرف الإسعافات الأولية، أم ننتظر سيارة الإسعاف؟",
        "services|2:1|3|p3": "سُرقت حقيبتي في المحطة، وأريد أن أبلغ عن السرقة.",
        "services|2:1|3|p4": "حاول ألا تصاب بالذعر، خذ نفسا عميقا وأخبرني بعنوانك.",
        "services|2:1|4|title": "مساعدة على الطريق السريع",
        "services|2:1|4|text": "كان رافي يقود سيارته من مانغالورو إلى أودوبي عندما رأى دراجة نارية ملقاة على جانب الطريق السريع. كان شاب جالسا بجانبها، وذراعه تنزف بشدة. أوقف رافي سيارته وقال لنفسه ألا يصاب بالذعر. اتصل بالرقم 108 وقال: «أريد أن أبلغ عن حادث، هناك شخص مصاب.» سأله موظف الاتصال عن الموقع بالضبط، فذكر رافي أقرب معلم، وهو منارة سوراتكال. وأثناء الانتظار، قدم رافي الإسعافات الأولية بالضغط بمنشفة نظيفة على الجرح. وصلت سيارة الإسعاف خلال خمس عشرة دقيقة، وفيما بعد شكر الشاب رافي لأنه بقي هادئا.",
        "services|2:1|4|q0": "أين رأى رافي الدراجة النارية؟",
        "services|2:1|4|q0o0": "على جانب الطريق السريع",
        "services|2:1|4|q0o1": "أمام مستشفى",
        "services|2:1|4|q0o2": "في موقف سيارات في أودوبي",
        "services|2:1|4|q0o3": "قرب بيته في مانغالورو",
        "services|2:1|4|q1": "أي معلم ذكره رافي؟",
        "services|2:1|4|q1o0": "منارة سوراتكال",
        "services|2:1|4|q1o1": "محطة بنزين",
        "services|2:1|4|q1o2": "معبد أودوبي",
        "services|2:1|4|q1o3": "موقف حافلات",
        "services|2:1|4|q2": "كم استغرقت سيارة الإسعاف لتصل؟",
        "services|2:1|4|q2o0": "خمس عشرة دقيقة",
