        "services|2:1|5|title": "الاتصال بالرقم 112",
        "services|2:1|5|scenario": "ترى نانديني دخانا يتصاعد من بيت في شارعها في بونه، فتتصل بخط الطوارئ 112. ويرد سوريش.",
        "services|2:1|5|l0": "خط الطوارئ 112. ما حالة الطوارئ لديك؟",
        "services|2:1|5|l1": "هناك حريق في بيت في شارعي. أرى دخانا كثيفا يخرج من نافذة الطابق العلوي.",
        "services|2:1|5|l2": "من فضلك حافظي على هدوئك يا سيدتي. هل ما زال أحد داخل البيت؟",
        "services|2:1|5|l3": "لست متأكدة. يسكن هناك زوجان مسنان، ولا أراهما في الخارج.",
        "services|2:1|5|l4": "سأرسل فرقة الإطفاء وسيارة إسعاف الآن. ما العنوان بالضبط؟",
        "services|2:1|5|l5": "البيت رقم 14، شانتي ناغار، كوثرود. والمعلم القريب هو خزان الماء الأزرق عند الزاوية.",
        "services|2:1|5|l6": "شكرا. من فضلك لا تدخلي، وأبعدي الناس الآخرين عن الدخان.",
        "services|2:1|5|l7": "حسنا. أوه، يقول أحد الجيران إن الزوجين في المعبد، فالبيت فارغ.",
        "services|2:1|5|l8": "هذا خبر جيد. يفترض أن تصل فرقة الإطفاء إليك خلال عشر دقائق تقريبا. من فضلك ابقي على الخط.",
        "services|2:1|5|l9": "شكرا جزيلا. أسمع صوت صفارة الإنذار بالفعل.",
        "services|2:1|5|q0": "لماذا اتصلت نانديني بالرقم 112؟",
        "services|2:1|5|q0o0": "رأت دخانا يخرج من بيت",
        "services|2:1|5|q0o1": "رأت حادث سير",
