        "services|3:1|1|p0": "صنبور المطبخ يقطر طوال الليل، هل يمكنكم إرسال سباك اليوم؟",
        "services|3:1|1|p1": "هناك تسرب تحت حوض الحمام، والأرضية مبللة دائما.",
        "services|3:1|1|p2": "كلما شغلت سخان الماء، يحترق الفيوز.",
        "services|3:1|1|p3": "يقول الكهربائي إن التمديدات الكهربائية القديمة في هذه الشقة غير آمنة.",
        "services|3:1|1|p4": "من فضلك أطفئ المفتاح الرئيسي قبل أن تلمس أي أسلاك.",
        "services|3:1|2|w0": "جهاز منزلي",
