        "services|3:1|2|w4": "تقدير التكلفة",
        "services|3:1|2|w5": "رسوم الخدمة",
        "services|3:1|3|p0": "في غسالتنا عطل، فهي تتوقف في منتصف كل غسلة.",
        "services|3:1|3|p1": "هل يمكن أن يأتي الفني غدا صباحا، قبل أن أخرج إلى العمل؟",
        "services|3:1|3|p2": "قبل أن تبدأ، هل يمكنك أن تعطيني تقديرا للتكلفة الإجمالية؟",
        "services|3:1|3|p3": "ستستغرق قطعة الغيار ثلاثة أيام لتصل من بنغالورو.",
        "services|3:1|3|p4": "رسوم الخدمة لأي جهاز منزلي كبير ثلاثمئة روبية لكل زيارة.",
        "services|3:1|4|title": "الثلاجة التي توقفت عن التبريد",
        "services|3:1|4|text": "خلال أسبوع حار من شهر مايو في كالابوراغي، توقفت ثلاجة عائلة كولكارني فجأة عن التبريد. اتصلت سونيتا بمركز خدمة الشركة وشرحت العطل بوضوح: الضوء يعمل، لكن الداخل دافئ. جاء فني في عصر اليوم التالي وفحص الجهاز بعناية. قال إن قطعة غيار في نظام التبريد قد تعطلت ويجب استبدالها. وقبل أن يبدأ، طلبت منه سونيتا بأدب تقديرا للتكلفة، فقال إن المجموع سيكون حوالي ألفي روبية، بما في ذلك رسوم الخدمة. وصلت القطعة من هوبالي بعد يومين، فأصلح الفني الثلاجة خلال ساعة. وفي ذلك المساء عادت الثلاجة باردة، واستطاعت العائلة أخيرا أن تحفظ الحليب واللبن.",
        "services|3:1|4|q0": "ما المشكلة في الثلاجة؟",
