        "services|3:1|5|scenario": "يتصل فرحان بآشا، التي تدير خدمة إصلاحات منزلية في ميسورو، لأن الفيوز في شقته يحترق باستمرار.",
        "services|3:1|5|l0": "صباح الخير، كويك فيكس للخدمات المنزلية. معك آشا. كيف يمكنني المساعدة؟",
        "services|3:1|5|l1": "مرحبا، أتصل بخصوص مشكلة كهربائية. الفيوز في شقتي يحترق باستمرار، غالبا في المساء.",
        "services|3:1|5|l2": "فهمت. هل يحدث ذلك عندما تشغل جهازا معينا؟",
        "services|3:1|5|l3": "أظن ذلك. يحدث عادة عندما يعمل سخان الماء والمكواة معا.",
        "services|3:1|5|l4": "قد يكون هناك عطل في التمديدات الكهربائية. يمكنني أن أرسل كهربائيا ليفحصها. متى يناسبك؟",
        "services|3:1|5|l5": "هل يمكنك أن ترسلي أحدا اليوم؟ أنا أعمل من البيت حتى السادسة.",
        "services|3:1|5|l6": "يستطيع الكهربائي ماهيش أن يأتي في الساعة الرابعة. رسوم الخدمة للزيارة مئتان وخمسون روبية.",
        "services|3:1|5|l7": "هذا مناسب. هل سيعطيني تقديرا للتكلفة قبل أن يبدأ أي إصلاح؟",
        "services|3:1|5|l8": "نعم، هو يشرح التكلفة أولا دائما. من فضلك أرسل عنوانك على واتساب.",
        "services|3:1|5|l9": "ممتاز، سأرسله الآن. شكرا.",
