        "services|4:1|3|p2": "إذا لم يتم الإصلاح قبل يوم الجمعة، فسأضطر إلى تصعيد شكواي.",
        "services|4:1|3|p3": "تأخر التوصيل عشرة أيام، وكان الطرد تالفا.",
        "services|4:1|3|p4": "نعتذر عن الإزعاج، وسنضيف مئتي روبية تعويضا لك.",
        "services|4:1|4|title": "مهذب لكن حازم",
        "services|4:1|4|text": "طلب عمران غلاية كهربائية عبر الإنترنت لأمه في بيلاغافي، لكن التوصيل تأخر أسبوعا. وعندما شغلتها، انبعثت من الغلاية رائحة احتراق وتوقفت عن العمل. اتصل عمران بخدمة العملاء، وأعطاهم رقم الطلب، وشرح أن المنتج معيب. عرض عليه الموظف الأول قسيمة فقط، فطلب عمران بأدب أن يتحدث مع مشرف. بقي هادئا لكن حازما وقال: «للأسف القسيمة لا تكفي، فالغلاية تحت الضمان، ومعي الإيصال.» اعتذرت المشرفة عن الإزعاج ووافقت على إرسال غلاية بديلة خلال يومين. وأضافت أيضا مئة روبية إلى حسابه تعويضا عن تأخر التوصيل.",
        "services|4:1|4|q0": "ما المشكلة في الغلاية؟",
