        "services|4:1|5|scenario": "تتصل ديبا بخط خدمة العملاء لمتجر إلكتروني لأنها استلمت كورتا خاطئة. ويرد براكاش على المكالمة.",
        "services|4:1|5|l0": "شكرا لاتصالك بخدمة عملاء شوب كارت. معك براكاش. كيف يمكنني مساعدتك؟",
        "services|4:1|5|l1": "مرحبا يا براكاش. أتصل بخصوص الطلب رقم 4582. استلمت منتجا خاطئا أمس.",
        "services|4:1|5|l2": "يؤسفني سماع ذلك. هل يمكنك أن تخبريني ماذا طلبت وماذا استلمت؟",
        "services|4:1|5|l3": "طلبت كورتا قطنية زرقاء بمقاس وسط، لكنني استلمت واحدة حمراء بمقاس كبير جدا.",
        "services|4:1|5|l4": "أعتذر عن الإزعاج. هل تريدين بديلا أم استرداد المبلغ؟",
        "services|4:1|5|l5": "أفضل استرداد المبلغ من فضلك. كنت أحتاجها لحفل زفاف يوم الأحد هذا، والبديلة لن تصل في الوقت المناسب.",
        "services|4:1|5|l6": "مفهوم. سيأتي شريك التوصيل لأخذ الطرد غدا بين العاشرة والثانية.",
