        "services|5:1|3|p4": "احتفظ بإيصال الاستلام هذا في مكان آمن، فستحتاجه لمتابعة طلبك.",
        "services|5:1|4|title": "صباح في مركز آدهار",
        "services|5:1|4|text": "انتقلت لاكشمي من شيفاموغا إلى بونه من أجل العمل، لذلك كانت تحتاج إلى تغيير العنوان في بطاقة آدهار. وصلت إلى مركز آدهار في الثامنة صباحا، لكن الطابور كان طويلا بالفعل. أعطاها حارس رقم دور هو اثنان وأربعون، واستمارة طلب لتملأها. وعندما جاء دورها، فحص الموظف مستنداتها وطلب نسخة مصورة من فاتورة الكهرباء لإثبات العنوان. ولحسن الحظ، كانت لاكشمي قد أحضرت نسختين، ووضعت توقيعها على كل صفحة مسبقا. ثم مسح الموظف بصمات أصابعها للتحقق، وطبع إيصال استلام. وأخبرها أن العنوان الجديد سيحدَّث خلال عشرة أيام، فغادرت لاكشمي المكتب قبل الظهر وهي مرتاحة.",
        "services|5:1|4|q0": "لماذا ذهبت لاكشمي إلى مركز آدهار؟",
