        "services|5:1|5|l0": "صباح الخير. هل يمكنني أن آخذ ورقة رقم الدور ونسخة الموعد المطبوعة من فضلك؟",
        "services|5:1|5|l1": "صباح الخير يا سيدتي. تفضلي. هذا أول طلب جواز سفر أقدمه.",
        "services|5:1|5|l2": "شكرا. أحتاج إلى بطاقة آدهار وإثبات عنوان آخر. ماذا أحضرت؟",
        "services|5:1|5|l3": "معي بطاقة آدهار، وشهادة الصف العاشر لإثبات تاريخ ميلادي، وفاتورة غاز حديثة.",
        "services|5:1|5|l4": "فاتورة الغاز باسم والدك. هل لديك شيء باسمك أنت؟",
        "services|5:1|5|l5": "للأسف لا، لكنني أحضرت نسخة مصورة من دفتر حسابي البنكي وعليه عنواني. هل يكفي ذلك؟",
        "services|5:1|5|l6": "نعم، هذا جيد. من فضلك وقّع هنا، ثم اذهب إلى الشباك بي لأخذ الصورة والبصمات.",
