        "services|6:1|1|p0": "كثيرا ما يطلب الملاك في بنغالورو إيجار عشرة أشهر كمبلغ تأمين.",
        "services|6:1|1|p1": "هل الإيجار قابل للتفاوض، أم هذا هو المبلغ النهائي؟",
        "services|6:1|1|p2": "يأخذ السمسار إيجار شهر واحد كأتعاب له.",
        "services|6:1|1|p3": "نبحث عن شقة مفروشة بالكامل قريبة من محطة المترو.",
