        "services|6:1|3|p0": "من فضلك اقرأ عقد الإيجار بعناية قبل أن توقعه.",
        "services|6:1|3|p1": "هل رسوم الصيانة الشهرية مشمولة في الإيجار، أم تدفع بشكل منفصل؟",
        "services|6:1|3|p2": "جيراننا ودودون، لكنهم يشغلون موسيقى صاخبة في وقت متأخر من الليل.",
        "services|6:1|3|p3": "مدة الإشعار شهران، لذلك يجب أن نخبر المالك قبل يوليو.",
        "services|6:1|3|p4": "عندما نخلي الشقة، سنسجل قراءة عداد الكهرباء.",
        "services|6:1|4|title": "شقة جديدة في ميسورو",
        "services|6:1|4|text": "بعد أن حصلت أنيتا على وظيفة في ميسورو، بدأت تبحث عن شقة صغيرة قرب كوفيمبوناغار. أراها سمسار أربعة أماكن، فأعجبتها شقة مفروشة بغرفة نوم واحدة في الطابق الثاني. طلب المالك، السيد غودا، اثني عشر ألف روبية في الشهر إيجارا، وستين ألفا مبلغ تأمين. سألته أنيتا بأدب إن كان يمكن تخفيض مبلغ التأمين قليلا، فاتفقا أخيرا على خمسين ألفا. وقبل أن توقع عقد الإيجار، تحققت من مدة الإشعار وسألت من سيدفع رسوم الصيانة الشهرية. كما التقطت صورة لعداد الكهرباء، حتى لا يحدث أي التباس بشأن الفواتير لاحقا. وفي أول مساء لها هناك، أحضرت لها جارة ودودة طبقا من البيسي بيلي باث الساخن.",
        "services|6:1|4|q0": "كم مبلغ التأمين الذي وافقت أنيتا على دفعه في النهاية؟",
        "services|6:1|4|q0o0": "خمسون ألف روبية",
