        "services|6:1|5|title": "اتصال بصاحبة البيت",
        "services|6:1|5|scenario": "راهول مستأجر في بونه، يتصل بصاحبة البيت، السيدة جوشي، بخصوص مشكلة في الشقة وبخصوص انتقاله منها.",
        "services|6:1|5|l0": "مساء الخير يا سيدة جوشي. معك راهول من الشقة 3 بي. هل لديك دقيقة؟",
        "services|6:1|5|l1": "نعم يا راهول، تفضل. هل كل شيء على ما يرام؟",
        "services|6:1|5|l2": "ليس تماما. الماء يتسرب من سقف الحمام منذ يوم الاثنين، والجدار أصبح رطبا.",
        "services|6:1|5|l3": "يا للأسف. لا بد أنه الخزان الذي على السطح. سأرسل السباك سونيل غدا صباحا.",
        "services|6:1|5|l4": "شكرا. هل ستُدفع تكلفة الإصلاح من رسوم الصيانة، أم يجب أن أدفعها أنا؟",
        "services|6:1|5|l5": "لا تقلق، هذه مسؤوليتي بصفتي صاحبة البيت. أنت تدفع فقط ثمن الأشياء الصغيرة مثل المصابيح.",
        "services|6:1|5|l6": "هذا لطف منك. وهناك أمر آخر: شركتي ستنقلني إلى ناشيك في مارس.",
        "services|6:1|5|l7": "فهمت. حسب العقد، مدة الإشعار شهران، فمن فضلك أعطني إشعارا مكتوبا بحلول يناير.",
        "services|6:1|5|l8": "سأرسل لك الإشعار بالبريد الإلكتروني هذا الأسبوع. وسيعاد إلي مبلغ التأمين عندما أخلي الشقة، صحيح؟",
        "services|6:1|5|l9": "نعم. بعد أن أفحص الشقة وفاتورة الكهرباء الأخيرة، سأحوله إليك خلال أسبوع.",
        "services|6:1|5|q0": "ما المشكلة التي يبلغ عنها راهول؟",
