        "workplace|1:1|3|p3": "ما يميزنا هو خبرتنا في الرعاية الصحية في الأرياف.",
        "workplace|1:1|3|p4": "نتخصص في مساعدة المتاجر في البلدات الصغيرة على بدء البيع عبر الإنترنت.",
        "workplace|1:1|4|title": "ماذا تعمل بالضبط؟",
        "workplace|1:1|4|text": "في حفل زفاف عائلي في دارواد، كان نيخيل يتحدث مع عمه، فسأله عمه عما يفعله بالضبط في عمله. شرح نيخيل أنه يعمل في شركة ناشئة تصنع أجهزة استشعار للتربة من أجل المزارعين. المقر الرئيسي للشركة في بنغالورو، لكن الأجهزة تصنع في مصنع صغير قرب هوبالي. مسماه الوظيفي مهندس منتجات، وهو جزء من قسم الاختبار. ومهمته الرئيسية هي فحص كل جهاز استشعار جديد قبل أن يرسل إلى المزارعين. كما يشرف على مهندسين مبتدئين اثنين، ويتعامل مع أسئلة فريق المصنع. ابتسم عمه وقال إن الشركة لا بد أن لديها عددا ضخما من الموظفين. فضحك نيخيل وقال إنهم أربعون شخصا فقط، لكن كل واحد منهم لديه خبرة حقيقية.",
        "workplace|1:1|4|q0": "ماذا تصنع شركة نيخيل؟",
