        "workplace|1:1|5|scenario": "في فعالية أعمال في بنغالورو، تلتقي أنانيا وفرحان لأول مرة ويتحدثان عن عملهما.",
        "workplace|1:1|5|l0": "مرحبا، أنا فرحان من شركة سهيادري للخدمات اللوجستية. ما الذي أتى بك إلى هذه الفعالية؟",
        "workplace|1:1|5|l1": "تشرفت بمعرفتك. أنا أنانيا. أرأس فريق دعم العملاء في شركة ناشئة للتكنولوجيا المالية.",
        "workplace|1:1|5|l2": "مثير للاهتمام. ماذا تفعل شركتك بالضبط؟",
        "workplace|1:1|5|l3": "طورنا تطبيقا يساعد أصحاب المتاجر الصغيرة على تنظيم حساباتهم وقبول المدفوعات الرقمية.",
        "workplace|1:1|5|l4": "وكيف يبدو يومك العادي؟",
        "workplace|1:1|5|l5": "أبدأ بمكالمة سريعة مع فريقي، ثم أتعامل بنفسي مع الشكاوى الصعبة.",
        "workplace|1:1|5|l6": "يبدو هذا متعبا. ما حجم فريقك؟",
