        "workplace|2:1|3|p2": "شاشتك متجمدة، هل يمكنك مشاركتها مرة أخرى؟",
        "workplace|2:1|3|p3": "أسمع صدى، لا بد أن سماعة حاسوب أحدكم قريبة جدا من الميكروفون.",
        "workplace|2:1|3|p4": "سأشارك التسجيل ورسالة متابعة قصيرة بالبريد الإلكتروني قبل هذا المساء.",
        "workplace|2:1|4|title": "المكالمة التي ظلت تتجمد",
        "workplace|2:1|4|text": "كل يوم اثنين، تستضيف ديبا مكالمة فيديو بين فريقها في ميسورو وفريق المبيعات في بونه. وفي الأسبوع الماضي، بدأت المكالمة بشكل سيئ. انضم اثنا عشر مشاركا، لكن ثلاثة منهم لم يتمكنوا من فتح الرابط. ثم ظهر صدى عال، لأن سوريش انضم من حاسوبه وهاتفه في الوقت نفسه. وعندما بدأت ديبا مشاركة شاشتها، تجمدت الشاشة، ووصل صوتها إلى بونه متأخرا كثيرا. طلبت بهدوء من الجميع أن يكتموا الصوت ويطفئوا كاميراتهم ويستخدموا سماعات الرأس. فتحسن الاتصال، وانتهى الاجتماع متأخرا عشر دقائق فقط. وفي ذلك المساء، أرسلت ديبا التسجيل ورسالة متابعة واضحة تذكر كل قرار وكل موعد نهائي.",
        "workplace|2:1|4|q0": "لماذا ظهر صدى عال؟",
