        "workplace|2:1|5|scenario": "ينضم كارتيك إلى اجتماع مشروع عبر الإنترنت من بيته في هوبالي. وتساعده ميرا، مضيفة الاجتماع، في الصوت والشاشة.",
        "workplace|2:1|5|l0": "مرحبا يا كارتيك، نراك، لكن صوتك مكتوم.",
        "workplace|2:1|5|l1": "آسف على ذلك. هل تسمعونني الآن؟",
        "workplace|2:1|5|l2": "نعم، بوضوح تام. هل يمكنك مشاركة شاشتك وشرح نتائج الاختبار لنا خطوة بخطوة؟",
        "workplace|2:1|5|l3": "بالتأكيد، أعطوني ثانية. هل يرى الجميع شاشتي؟",
        "workplace|2:1|5|l4": "نرى جدول بيانات، لكن يبدو أنه متجمد.",
        "workplace|2:1|5|l5": "اتصالي ينقطع باستمرار. دعوني أطفئ الفيديو وأحاول مرة أخرى.",
        "workplace|2:1|5|l6": "أفضل بكثير، إنها تتحرك الآن. تفضل، أكمل.",
        "workplace|2:1|5|l7": "شكرا. كما ترون، نجحت تسعون في المئة من اختبارات هذا الأسبوع.",
        "workplace|2:1|5|l8": "عمل رائع. أنا أسجل هذا الاجتماع، حتى يتمكن فريق بونه من مشاهدته لاحقا.",
        "workplace|2:1|5|l9": "ممتاز. وسأرسل أيضا رسالة متابعة قصيرة بالاختبارات الفاشلة بعد المكالمة.",
        "workplace|2:1|5|q0": "ما أول مشكلة واجهها كارتيك؟",
        "workplace|2:1|5|q0o0": "كان صوته مكتوما",
        "workplace|2:1|5|q0o1": "لم يكن لديه حاسوب محمول",
        "workplace|2:1|5|q0o2": "انضم إلى الاجتماع الخطأ",
        "workplace|2:1|5|q0o3": "كانت كاميرته معطلة",
        "workplace|2:1|5|q1": "كيف حل كارتيك مشكلة الشاشة المتجمدة؟",
        "workplace|2:1|5|q1o0": "أطفأ الفيديو",
        "workplace|2:1|5|q1o1": "اشترى سماعة رأس جديدة",
        "workplace|2:1|5|q1o2": "اتصل بميرا على الهاتف",
        "workplace|2:1|5|q1o3": "ذهب إلى المكتب",
        "workplace|2:1|5|q2": "لماذا تسجل ميرا الاجتماع؟",
        "workplace|2:1|5|q2o0": "حتى يتمكن فريق بونه من مشاهدته لاحقا",
        "workplace|2:1|5|q2o1": "لتعرف من تأخر",
