        "workplace|3:1|0|w0": "شريحة",
        "workplace|3:1|0|w1": "مخطط عام",
        "workplace|3:1|0|w2": "نظرة عامة",
        "workplace|3:1|0|w3": "رسم بياني",
        "workplace|3:1|0|w4": "يُبرز",
        "workplace|3:1|0|w5": "رقم",
        "workplace|3:1|1|p0": "دعوني أبدأ بنظرة عامة سريعة على ما سنتناوله اليوم.",
        "workplace|3:1|1|p1": "كما ترون في هذه الشريحة، تضاعفت المبيعات بعد شهر مارس.",
        "workplace|3:1|1|p2": "جعلت المخطط العام بسيطا: المشكلة، والحل، والتكلفة، والجدول الزمني.",
        "workplace|3:1|1|p3": "يوضح هذا الرسم البياني أرقامنا الشهرية في السنتين الأخيرتين.",
        "workplace|3:1|1|p4": "أود أن أبرز رقما واحدا بالتحديد: انخفضت تكاليفنا بنسبة اثني عشر في المئة.",
        "workplace|3:1|2|w0": "جهاز العرض",
        "workplace|3:1|2|w1": "يتدرّب",
        "workplace|3:1|2|w2": "نشرة مطبوعة",
        "workplace|3:1|2|w3": "يوضّح",
        "workplace|3:1|2|w4": "يختتم",
        "workplace|3:1|2|w5": "يلخّص",
        "workplace|3:1|3|p0": "هل يمكن لأحد أن يتحقق من جهاز العرض؟ الشرائح تبدو داكنة جدا.",
        "workplace|3:1|3|p1": "تدربت على العرض كله مرتين، لذلك أعرف بالضبط كم يستغرق.",
        "workplace|3:1|3|p2": "هناك نشرة مطبوعة فيها كل الأرقام، فلا داعي لأن تدونوا ملاحظات.",
        "workplace|3:1|3|p3": "هذا سؤال جيد، دعوني أوضح ما قصدته بالتكلفة الإجمالية.",
        "workplace|3:1|3|p4": "وفي الختام، دعوني ألخص النقاط الرئيسية الثلاث في دقيقة واحدة.",
        "workplace|3:1|4|title": "يوم ريكها الكبير",
        "workplace|3:1|4|text": "كان على ريكها، وهي مسؤولة تسويق في هوبالي، أن تعرض النتائج السنوية على مديري الشركة. أعدت مخططا عاما بسيطا وثماني شرائح فقط، في كل منها رسم بياني واضح واحد. وفي الليلة السابقة، تدربت على العرض كله ثلاث مرات أمام أختها. وفي يوم العرض، توقف جهاز العرض في قاعة الاجتماعات عن العمل قبل أن تبدأ بخمس دقائق. ولحسن الحظ، كانت ريكها قد طبعت نشرات فيها كل الأرقام المهمة. بدأت بنظرة عامة قصيرة، ثم أبرزت مقدار انخفاض تكاليف التوصيل. وعندما سأل أحد المديرين عن المتجر الجديد في بيلاغافي، وضحت الأرقام بهدوء. واختتمت بتلخيص نقاطها الرئيسية الثلاث، فشكرها المديرون على وضوحها.",
        "workplace|3:1|4|q0": "كم شريحة أعدت ريكها؟",
        "workplace|3:1|4|q0o0": "ثماني شرائح",
        "workplace|3:1|4|q0o1": "ثلاث شرائح",
        "workplace|3:1|4|q0o2": "اثنتا عشرة شريحة",
        "workplace|3:1|4|q0o3": "عشرون شريحة",
