        "workplace|3:1|4|q1o0": "توقف جهاز العرض عن العمل",
        "workplace|3:1|4|q1o1": "نسيت ريكها شرائحها",
        "workplace|3:1|4|q1o2": "وصل المديرون متأخرين",
