        "workplace|3:1|5|title": "تجربة قبل العرض",
        "workplace|3:1|5|scenario": "يتدرب سانجاي على عرض لأحد العملاء مع مديرته لاكشمي في مكتبهما في بونه.",
        "workplace|3:1|5|l0": "حسنا يا سانجاي، تخيل أنني العميل. ابدأ عندما تكون مستعدا.",
        "workplace|3:1|5|l1": "صباح الخير جميعا، وشكرا لاستضافتنا. اليوم أود أن أعرض عليكم خطوة بخطوة خطتنا لموقعكم الإلكتروني الجديد.",
        "workplace|3:1|5|l2": "بداية جيدة. كيف ستنظم العرض؟",
        "workplace|3:1|5|l3": "سأتناول ثلاثة أمور: ما وجدناه، وما نقترحه، وكم سيكلف.",
        "workplace|3:1|5|l4": "واضح وجميل. وماذا لو قاطعك العميل بسؤال في منتصف العرض؟",
        "workplace|3:1|5|l5": "سأشكره، وأدون السؤال، وأقول إنني سأعود إليه في النهاية.",
        "workplace|3:1|5|l6": "جيد. وماذا في شريحتك الأخيرة؟",
        "workplace|3:1|5|l7": "ملخص للنقاط الثلاث وخطوة تالية واضحة: اجتماع يوم الجمعة القادم.",
        "workplace|3:1|5|l8": "ممتاز. فقط تمهل قليلا، وانظر إلى الحضور، لا إلى الشاشة.",
        "workplace|3:1|5|l9": "شكرا يا لاكشمي. سأتدرب عليه مرة أخرى الليلة.",
        "workplace|3:1|5|q0": "ماذا يعرض سانجاي؟",
        "workplace|3:1|5|q0o0": "خطة لموقع إلكتروني جديد لعميل",
        "workplace|3:1|5|q0o1": "نتائج المبيعات السنوية",
        "workplace|3:1|5|q0o2": "مبنى مكاتب جديدا",
        "workplace|3:1|5|q0o3": "دورة تدريبية",
        "workplace|3:1|5|q1": "ماذا سيفعل سانجاي إذا قاطعه العميل؟",
