        "workplace|4:1|0|w5": "عرض توضيحي",
        "workplace|4:1|1|p0": "قبل أن نقترح أي شيء، هل يمكنك أن تخبرنا أكثر عن متطلباتك؟",
        "workplace|4:1|1|p1": "سنرسل لك مقترحا مفصلا وعرض سعر قبل يوم الخميس.",
        "workplace|4:1|1|p2": "جدولنا الزمني التقريبي ستة أسابيع، لكنني سأؤكد بعد زيارة الموقع.",
        "workplace|4:1|1|p3": "هل سيساعدك عرض توضيحي قصير على تحديد الخطة التي تناسبك؟",
        "workplace|4:1|1|p4": "هذا العميل يريد كل شيء باللغة الكنادية، بما في ذلك شاشات التطبيق.",
        "workplace|4:1|2|w0": "يشحن",
