        "workplace|4:1|2|w2": "إحباط",
        "workplace|4:1|2|w3": "يُعفي من",
        "workplace|4:1|2|w4": "التزام",
        "workplace|4:1|2|w5": "يطمئن",
        "workplace|4:1|3|p0": "سيشحن طلبك من مستودعنا في بونه يوم الاثنين.",
        "workplace|4:1|3|p1": "الفاتورة تظهر مبلغا خاطئا، لذلك سأطلب من قسم الحسابات تصحيحها.",
        "workplace|4:1|3|p2": "أتفهم إحباطك، وسأرفع هذا الأمر إلى مديري اليوم.",
        "workplace|4:1|3|p3": "تعويضا عن التأخير، سنعفيك من رسوم التوصيل هذه المرة.",
        "workplace|4:1|3|p4": "أؤكد لك أن البديل سيصلك قبل يوم الجمعة، وهذا التزام شخصي مني.",
        "workplace|4:1|4|title": "بطاقات قائمة الطعام التي لم تصل أبدا",
        "workplace|4:1|4|text": "يدير عمران حسابات العملاء في شركة طباعة في بنغالورو. وفي أحد أيام الاثنين، اتصلت به السيدة شيتي، التي تدير فندقا في ميسورو، وهي منزعجة جدا. لم تصل بطاقات قائمة الطعام الجديدة الخاصة بها، مع أن عرض السعر وعد بالتوصيل خلال أسبوع. استمع عمران دون أن يقاطعها، ثم أعاد متطلباتها ليتأكد من أنه فهمها. واكتشف أن الطلب لم يشحن أبدا بسبب خطأ في الفاتورة. فرفع المشكلة إلى مديره، ورتب إرسالها مع شركة شحن في عصر اليوم نفسه. وتعويضا للسيدة شيتي عن التأخير، خصمت الشركة عشرة في المئة من الفاتورة. وطمأنها عمران بأنه سيتابع طلباتها القادمة بنفسه، فبقيت عميلة لدى الشركة.",
        "workplace|4:1|4|q0": "لماذا كانت السيدة شيتي منزعجة؟",
        "workplace|4:1|4|q0o0": "لم تصل بطاقات قائمة الطعام",
        "workplace|4:1|4|q0o1": "كانت في البطاقات أخطاء إملائية",
        "workplace|4:1|4|q0o2": "كان السعر مرتفعا جدا",
        "workplace|4:1|4|q0o3": "لم يرد عمران على مكالمتها",
        "workplace|4:1|4|q1": "لماذا لم يشحن الطلب؟",
        "workplace|4:1|4|q1o0": "كان هناك خطأ في الفاتورة",
