        "workplace|4:1|5|title": "عميل جديد",
        "workplace|4:1|5|scenario": "نيها، مديرة مبيعات في شركة أثاث في هوبالي، تتلقى مكالمة من فيكرام كولكارني، الذي يحتاج إلى أثاث لمكتب جديد.",
        "workplace|4:1|5|l0": "مساء الخير يا سيد كولكارني. شكرا لتواصلك معنا. كيف يمكننا المساعدة؟",
        "workplace|4:1|5|l1": "سنفتتح مكتبا جديدا في بيلاغافي ونحتاج إلى مكاتب وكراس لأربعين شخصا.",
        "workplace|4:1|5|l2": "رائع. هل يمكنك أن تخبرني أكثر عن متطلباتكم؟ هل في ذهنك ميزانية أو طراز معين؟",
        "workplace|4:1|5|l3": "شيء بسيط ومريح. ميزانيتنا حوالي ثمانمئة ألف روبية.",
        "workplace|4:1|5|l4": "هذا ممكن تماما. متى تحتاجون إلى توصيل كل شيء؟",
        "workplace|4:1|5|l5": "بحلول الخامس عشر من الشهر القادم. هذا التاريخ مهم جدا لنا.",
        "workplace|4:1|5|l6": "مفهوم. سأرسل لك مقترحا فيه خياران وعرض سعر قبل يوم الجمعة.",
        "workplace|4:1|5|l7": "هل يمكن لفريقكم أيضا أن يتولى التركيب في الموقع؟",
        "workplace|4:1|5|l8": "نعم، التركيب مشمول. وأؤكد لك أننا سنلتزم بموعدكم النهائي.",
        "workplace|4:1|5|l9": "رائع. سأنتظر مقترحكم إذن.",
