        "workplace|5:1|3|p2": "سأسلم العمل بشكل كامل يوم الخميس حتى لا يفوتنا شيء.",
        "workplace|5:1|3|p3": "هل يمكن أن نعيد جدولة مراجعتنا إلى الأسبوع القادم؟ أنا في إجازة يوم الاثنين.",
        "workplace|5:1|3|p4": "مديرنا مرن، بشرط أن نطلب مسبقا بأسبوع على الأقل.",
        "workplace|5:1|4|title": "زفاف في أودوبي",
        "workplace|5:1|4|text": "تعمل سوميا في فريق المدفوعات في المقر الرئيسي لأحد البنوك في بنغالورو. وكان زفاف ابن عمها في أودوبي في الأسبوع الأخير من مارس، وهو أكثر أوقات السنة انشغالا. تحققت من رصيد إجازاتها ووجدت أنه ما زال لديها تسعة أيام. وقبل ثلاثة أسابيع، طلبت من مديرها، السيد بهات، إجازة لأربعة أيام وشرحت له السبب بأدب. كما عرضت أن تعمل من البيت في اليوم التالي للزفاف. كان السيد بهات مرنا، لكنه سأل عمن سينوب عنها في تقارير نهاية الشهر. فبدلت سوميا نوبتين مع زميلها راكيش، ووعدت بتسليم العمل كاملا قبل أن تسافر. ولأن السيد بهات كان راضيا عن خطتها، وافق على الإجازة في عصر اليوم نفسه.",
        "workplace|5:1|4|q0": "لماذا احتاجت سوميا إلى إجازة؟",
        "workplace|5:1|4|q0o0": "لحضور زفاف ابن عمها في أودوبي",
        "workplace|5:1|4|q0o1": "لأنها كانت مريضة",
        "workplace|5:1|4|q0o2": "لدورة تدريبية",
        "workplace|5:1|4|q0o3": "للانتقال إلى بيت جديد",
        "workplace|5:1|4|q1": "كم يوما من الإجازة كان لا يزال لديها؟",
