        "workplace|5:1|5|title": "مكالمة في الصباح الباكر",
        "workplace|5:1|5|scenario": "يتصل أرون بقائدة فريقه، شاليني، في الصباح الباكر لأن أمه مريضة.",
        "workplace|5:1|5|l0": "صباح الخير يا شاليني. آسف لأنني أتصل مبكرا هكذا. هل لديك دقيقة؟",
        "workplace|5:1|5|l1": "بالطبع يا أرون. هل كل شيء على ما يرام؟",
        "workplace|5:1|5|l2": "ليس تماما. سقطت أمي ليلة أمس، ويجب أن آخذها إلى المستشفى لإجراء بعض الفحوصات.",
        "workplace|5:1|5|l3": "أوه، يؤسفني سماع ذلك. اعتن بها من فضلك. هل ستحتاج إلى اليوم كله؟",
        "workplace|5:1|5|l4": "أظن ذلك. أود أن آخذ اليوم إجازة، وربما أعمل من البيت غدا.",
        "workplace|5:1|5|l5": "لا بأس. وماذا عن مكالمة العميل في الساعة الثالثة؟",
        "workplace|5:1|5|l6": "ديباك يعرف المشروع جيدا. سألته بالفعل، وهو مستعد أن ينوب عني.",
        "workplace|5:1|5|l7": "جيد. من فضلك أرسل له ملاحظاتك، وقدم طلب الإجازة على البوابة الإلكترونية عندما تستطيع.",
        "workplace|5:1|5|l8": "سأفعل ذلك خلال ساعة. شكرا لتفهمك يا شاليني.",
        "workplace|5:1|5|l9": "لا مشكلة. أتمنى أن تتحسن أمك قريبا.",
        "workplace|5:1|5|q0": "لماذا يحتاج أرون إلى إجازة؟",
