        "workplace|6:1|1|p0": "بشكل عام، كان أداؤك هذا العام قويا جدا.",
        "workplace|6:1|1|p1": "أكبر نقاط قوتك هي هدوؤك في التعامل مع العملاء الغاضبين.",
        "workplace|6:1|1|p2": "هل تسمح لي أن أقدم لك بعض الملاحظات البناءة حول عرض أمس؟",
        "workplace|6:1|1|p3": "في تقييمي الذاتي، ذكرت إدارة الوقت كنقطة ضعف.",
        "workplace|6:1|1|p4": "كان افتتاح فرع ميسورو في موعده علامة فارقة حقيقية لفريقنا.",
        "workplace|6:1|2|w0": "مرشد",
