        "workplace|6:1|2|w5": "يستحق",
        "workplace|6:1|3|p0": "أود أن أطور مهاراتي في تحليل البيانات، فهل يمكن للشركة أن تدعم دورة قصيرة؟",
        "workplace|6:1|3|p1": "اقترح مرشدي أن أحصل على شهادة في الحوسبة السحابية قبل التقدم لمنصب القائد.",
        "workplace|6:1|3|p2": "يرى مديرك أن لديك الإمكانات لقيادة فريق خلال سنتين.",
        "workplace|6:1|3|p3": "هذا العام، سيحصل كل أعضاء الفريق على زيادة لا تقل عن ثمانية في المئة.",
        "workplace|6:1|3|p4": "أعتقد أنني أستحق ترقية، وأود أن نناقش الخطوة التالية.",
        "workplace|6:1|4|title": "يوم تقييم الأداء",
        "workplace|6:1|4|text": "في كل أبريل، تعقد شركة فريدة في مانغالورو اجتماعات تقييم الأداء السنوية. وقبل اجتماعها، كتبت فريدة تقييما ذاتيا صادقا، ذكرت فيه نقاط قوتها ونقطة ضعف واضحة واحدة: أنها نادرا ما تطلب المساعدة. بدأ مديرها، السيد راو، بالثناء على أدائها في نظام الفوترة الجديد، الذي كان علامة فارقة كبيرة للفريق. ثم قدم لها بعض الملاحظات البناءة حول مشاركة المشكلات في وقت أبكر. شكرته فريدة وطلبت تدريبا في إدارة المشاريع. فوافق السيد راو على دفع تكاليف دورة للحصول على شهادة معتمدة، وعلى أن يجد لها مرشدا من كبار الموظفين. وقال إن لديها الإمكانات لقيادة فريق يوما ما، وإنها تستحق زيادة جيدة. وغادرت فريدة الاجتماع بخطة واضحة للعام المقبل.",
        "workplace|6:1|4|q0": "ما نقطة الضعف التي كتبتها فريدة؟",
        "workplace|6:1|4|q0o0": "أنها نادرا ما تطلب المساعدة",
        "workplace|6:1|4|q0o1": "أنها كثيرا ما تتأخر",
        "workplace|6:1|4|q0o2": "أنها تتكلم بسرعة كبيرة",
        "workplace|6:1|4|q0o3": "أنها ترتكب أخطاء في الفوترة",
        "workplace|6:1|4|q1": "ماذا طلبت فريدة؟",
        "workplace|6:1|4|q1o0": "تدريبا في إدارة المشاريع",
