        "workplace|6:1|4|q2o3": "أن يلغي تقييمها",
        "workplace|6:1|5|title": "المراجعة السنوية",
        "workplace|6:1|5|scenario": "لدى راميش اجتماع تقييم الأداء السنوي مع مديرته سونيتا في مكتبهما في بنغالورو.",
        "workplace|6:1|5|l0": "شكرا لحضورك يا راميش. لنبدأ بتقييمك الذاتي. كيف ترى أن العام مضى؟",
        "workplace|6:1|5|l1": "أظن أنه مضى بشكل جيد. سلمنا تطبيق الدفع في موعده، ودربت موظفين جديدين.",
        "workplace|6:1|5|l2": "أوافقك. كان أداؤك في التطبيق ممتازا، وقد ذكر العميل عملك بشكل خاص.",
        "workplace|6:1|5|l3": "يسعدني سماع ذلك. هل هناك شيء تريدينني أن أحسنه؟",
        "workplace|6:1|5|l4": "أمر واحد فقط. في الاجتماعات تبقى صامتا في الغالب، حتى عندما تكون لديك أفكار جيدة. أريدك أن تتكلم أكثر.",
        "workplace|6:1|5|l5": "هذا عادل. سأحاول أن أشارك أفكاري في وقت أبكر. وهل يمكنني أيضا أن أطلب بعض التدريب؟",
        "workplace|6:1|5|l6": "بالطبع. ماذا يدور في ذهنك؟",
        "workplace|6:1|5|l7": "دورة في الخطابة أمام الجمهور، وربما مرشدا من فريق كبار الموظفين.",
        "workplace|6:1|5|l8": "كلاهما فكرة جيدة. سأتحدث مع الموارد البشرية هذا الأسبوع. استمر على هذا المستوى، ويمكننا أن نناقش منصب قائد فريق في العام القادم.",
        "workplace|6:1|5|l9": "شكرا يا سونيتا. أقدّر دعمك كثيرا.",
        "workplace|6:1|5|q0": "ماذا ذكر العميل بشكل خاص؟",
