        "opinions|1:1|0|w3": "موقف",
        "opinions|1:1|0|w4": "اقتناع راسخ",
        "opinions|1:1|0|w5": "بصراحة",
        "opinions|1:1|1|p0": "في رأيي، يجب أن يتعلم كل طفل العزف على آلة موسيقية واحدة على الأقل.",
        "opinions|1:1|1|p1": "بالنسبة لي، جدول مواعيد الحافلات الجديد تحسن كبير.",
        "opinions|1:1|1|p2": "ما موقفك من الهواتف المحمولة في الفصل؟",
        "opinions|1:1|1|p3": "تحدثت باقتناع شديد لدرجة أن أحدا في الغرفة لم يجادلها.",
        "opinions|1:1|1|p4": "بصراحة، وجدت الفيلم طويلا جدا ومملا إلى حد ما.",
        "opinions|1:1|2|w0": "منطق",
        "opinions|1:1|2|w1": "على سبيل المثال",
        "opinions|1:1|2|w2": "افتراض",
        "opinions|1:1|2|w3": "إحساس داخلي",
        "opinions|1:1|2|w4": "بشكل عام",
        "opinions|1:1|2|w5": "قابل للنقاش",
        "opinions|1:1|3|p0": "منطقك واضح، لكنني أود أن أسمع بعض الأمثلة.",
        "opinions|1:1|3|p1": "قد تكون الحياة في البلدات الصغيرة جميلة، فأودوبي، على سبيل المثال، هادئة ونظيفة.",
        "opinions|1:1|3|p2": "هذا مجرد افتراض، هل لديك أي حقائق تدعمه؟",
        "opinions|1:1|3|p3": "كان لدي إحساس داخلي بأن الطريق المختصر عبر الغابة فكرة سيئة.",
        "opinions|1:1|3|p4": "بشكل عام، أظن أن الدروس عبر الإنترنت نجحت أكثر مما توقعنا.",
        "opinions|1:1|4|title": "مناظرة في دارواد",
        "opinions|1:1|4|text": "في كل عام، تعقد إحدى الكليات في دارواد مناظرة حول سؤال يهم الطلاب. وكان موضوع هذا العام: هل يجب استبدال الامتحانات بالمشاريع؟ تحدثت ميغانا أولا، وفي رأيها أن المشاريع تعلم الطلاب التفكير بدلا من الحفظ. وقدمت مثالا واضحا من مدرستها، حيث علمها مشروع علمي واحد أكثر مما علمها أي امتحان. أما روهان فلم يوافق، وقال بصراحة إن المشاريع قد تكون غير عادلة، لأن عددا قليلا من الطلاب ينتهي بهم الأمر إلى القيام بكل العمل. كان منطقه قويا، لكن بعض نقاطه كانت قابلة للنقاش. وبشكل عام، رأى الحكام أن ميغانا قدمت أمثلة أفضل. وبعد المناظرة، ذهب الصديقان لشرب الشاي، وظلا يتجادلان بسعادة لساعة أخرى.",
        "opinions|1:1|4|q0": "ما موضوع المناظرة؟",
        "opinions|1:1|4|q0o0": "هل يجب استبدال الامتحانات بالمشاريع",
        "opinions|1:1|4|q0o1": "هل يجب السماح بالهواتف في الكلية",
        "opinions|1:1|4|q0o2": "هل يجب أن يرتدي الطلاب زيا موحدا",
        "opinions|1:1|4|q0o3": "هل يجب أن يبدأ الدوام في الكلية متأخرا",
        "opinions|1:1|4|q1": "ما أكثر ما يقلق روهان بشأن المشاريع؟",
        "opinions|1:1|4|q1o0": "أن عددا قليلا من الطلاب يقومون بكل العمل",
        "opinions|1:1|4|q1o1": "أن المشاريع تكلف مالا كثيرا",
        "opinions|1:1|4|q1o2": "أن تصحيح المشاريع يستغرق وقتا طويلا",
        "opinions|1:1|4|q1o3": "أن المعلمين لا يحبون المشاريع",
        "opinions|1:1|4|q2": "ماذا فعل الصديقان بعد المناظرة؟",
        "opinions|1:1|4|q2o0": "شربا الشاي وظلا يتجادلان بسعادة",
        "opinions|1:1|4|q2o1": "عادا إلى البيت دون أن يتكلما",
        "opinions|1:1|4|q2o2": "كتبا مشروعا معا",
        "opinions|1:1|4|q2o3": "تناولا العشاء مع الحكام",
        "opinions|1:1|5|title": "الهواتف على مائدة العشاء",
        "opinions|1:1|5|scenario": "أنجالي وأخوها الأصغر كيران، في بيتهما في ميسورو، يناقشان قاعدة عائلية جديدة.",
        "opinions|1:1|5|l0": "كيران، أمي تريد قاعدة جديدة: لا هواتف على مائدة العشاء. ما رأيك؟",
        "opinions|1:1|5|l1": "بصراحة، أظن أنها صارمة قليلا. أحيانا أحتاج إلى الرد على أصدقائي.",
        "opinions|1:1|5|l2": "بالنسبة لي، العشاء هو الوقت الوحيد الذي نجلس فيه كلنا معا.",
        "opinions|1:1|5|l3": "هذا صحيح، لكن ماذا لو وصلت رسالة عاجلة؟",
        "opinions|1:1|5|l4": "عندها يمكنك أن تبتعد لدقيقة. على سبيل المثال، أبي يفعل ذلك مع مكالمات العمل.",
        "opinions|1:1|5|l5": "همم. بشكل عام، أظن أنها عادلة، لكن للعشاء فقط، لا للغداء.",
        "opinions|1:1|5|l6": "في رأيي، هذا اتفاق معقول. هل نخبر أمي معا؟",
        "opinions|1:1|5|l7": "نعم، لكن يجب أن يعرف الجميع أنني لم أوافق إلا بعد نقاش طويل!",
        "opinions|1:1|5|l8": "تم التسجيل. لقد استمعنا إلى موقفك يا حضرة القاضي.",
        "opinions|1:1|5|l9": "مضحك جدا. هيا نأكل قبل أن يبرد الطعام.",
        "opinions|1:1|5|q0": "ما القاعدة التي تريدها الأم؟",
        "opinions|1:1|5|q0o0": "لا هواتف على مائدة العشاء",
