        "opinions|2:1|3|p1": "اسمح لي أن أختلف معك، فالسوق القديم له طابع مميز أكثر بكثير من المركز التجاري.",
        "opinions|2:1|3|p2": "بعد أن استمعت المديرة إلى الطرفين، وافقت على إعادة النظر في قرارها.",
        "opinions|2:1|3|p3": "كان ضد الرحلة في البداية، لكنه غير رأيه بعد ذلك.",
