        "opinions|2:1|4|title": "آخر رحلة مدرسية",
        "opinions|2:1|4|text": "كان على طلاب الصف الثاني عشر في هاسان أن يختاروا مكانا لآخر رحلة مدرسية لهم. أراد نيخيل الذهاب إلى غوكارنا من أجل الشاطئ، لكن ديفيا أرادت هامبي من أجل تاريخها. في البداية لم يتفق الاثنان، وعلت الأصوات في النقاش. ثم قالت ديفيا: «مع احترامي، الشاطئ ممتع، لكن هامبي شيء سنتذكره طوال حياتنا.» اعترف نيخيل بأن لديها نقطة وجيهة، لكنه كان قلقا من الحر. فساعدتهما معلمتهما على إيجاد أرضية مشتركة: سيستكشفون هامبي في الصباح البارد، ويستريحون عند نهر تونغابهادرا بعد الظهر. وفي النهاية غير نيخيل رأيه وصوت لهامبي بنفسه. وبعد شهر، اتفق الجميع على أنها كانت أفضل رحلة قاموا بها في حياتهم.",
        "opinions|2:1|4|q0": "لماذا أراد نيخيل الذهاب إلى غوكارنا؟",
