        "opinions|2:1|5|title": "التخطيط لمهرجان الكلية",
        "opinions|2:1|5|scenario": "بوجا وسمير، طالبان في لجنة مهرجان إحدى الكليات في مانغالورو، يختلفان حول طريقة إنفاق المال.",
        "opinions|2:1|5|l0": "سمير، سمعت أنك تريد دعوة نجم سينمائي إلى مهرجان الكلية. هل هذا صحيح؟",
        "opinions|2:1|5|l1": "نعم! اسم كبير سيجلب حشودا ضخمة. ألا تظنين ذلك؟",
        "opinions|2:1|5|l2": "إلى حد ما، نعم. لكن مع احترامي، أجر النجم سيلتهم نصف أموالنا.",
        "opinions|2:1|5|l3": "هذه نقطة وجيهة. ومع ذلك، مهرجان بلا نجم يبدو عاديا بعض الشيء.",
        "opinions|2:1|5|l4": "اسمح لي أن أختلف معك. في العام الماضي كانت فرقة الياكشاغانا من أودوبي أفضل ما في المهرجان.",
        "opinions|2:1|5|l5": "همم، أتفق معك تماما بشأن ذلك العرض. كان الجميع يرقصون في النهاية.",
        "opinions|2:1|5|l6": "إذن لماذا لا ندعوهم مرة أخرى وننفق الباقي على طعام وإضاءة أفضل؟",
        "opinions|2:1|5|l7": "حسنا، لقد غيرت رأيي. سأعيد النظر وأتحدث مع اللجنة غدا.",
        "opinions|2:1|5|l8": "شكرا لأنك منفتح إلى هذا الحد. أعرف أنها كانت فكرتك المفضلة.",
        "opinions|2:1|5|l9": "حسنا، ما زال بإمكاننا أن نتفق على أن نختلف حول من هو أفضل نجم سينمائي!",
