        "opinions|3:1|3|p3": "كان مشرف السكن الداخلي يعرف كل شقاوتنا، لكنه كان يتظاهر بأنه لا يلاحظ.",
        "opinions|3:1|3|p4": "أحتفظ بقلم الحبر القديم هذا تذكارا من معلمي المفضل.",
        "opinions|3:1|4|title": "المساء الممطر في كوداغو",
        "opinions|3:1|4|text": "نشأت شريا في قرية صغيرة في كوداغو، حيث كانت عائلتها تزرع البن. وهي لا تتذكر معظم طفولتها إلا بشكل غامض، لكن يوما واحدا ما زال حيا في ذهنها. عندما كانت في العاشرة، تسبب مطر غزير في فيضان النهر، فلم تستطع حافلة المدرسة عبور الجسر. انتظر الأطفال ساعات في البرد، حتى وصل مزارع اسمه بونابا بجراره. فنقل الأطفال الثلاثين جميعا عبر الماء، اثنين أو ثلاثة في كل مرة. وما زالت شريا تحتفظ بالمنشفة الصغيرة التي أعطاها إياها تذكارا. وكلما هطل مطر غزير، تعود إليها فجأة ذكرى ذلك المساء. لقد كان ذلك نقطة تحول في حياتها: ففي ذلك اليوم قررت أن تقضي هي أيضا حياتها في مساعدة الناس.",
        "opinions|3:1|4|q0": "لماذا لم تستطع حافلة المدرسة أن تعيد الأطفال إلى بيوتهم؟",
        "opinions|3:1|4|q0o0": "فاض النهر ولم تستطع الحافلة عبور الجسر",
