        "opinions|3:1|5|title": "أيام جدي في المدرسة",
        "opinions|3:1|5|scenario": "تتحدث أنانيا مع جدها نارايان في مانديا عن أيام دراسته من أجل مشروع مدرسي.",
        "opinions|3:1|5|l0": "يا جدي، من أجل مشروعي، هل يمكنك أن تخبرني كيف كانت المدرسة عندما كنت صغيرا؟",
        "opinions|3:1|5|l1": "آه، كانت تلك أياما مختلفة. كنا نمشي أربعة كيلومترات إلى المدرسة كل يوم.",
        "opinions|3:1|5|l2": "أربعة كيلومترات! ألم تكن لديكم حافلة أو دراجة؟",
        "opinions|3:1|5|l3": "لم يكن أحد في قريتنا يملك دراجة. كنا نمشي حفاة ونغني الأغاني في الطريق.",
        "opinions|3:1|5|l4": "ما أوضح ذكرى لديك من تلك الأيام؟",
        "opinions|3:1|5|l5": "اليوم الذي أمسك بي فيه المدير وأنا أسرق المانجو من شجرته. ما زلت أرى وجهه!",
        "opinions|3:1|5|l6": "يا جدي، لم أكن أعرف أنك كنت شقيا إلى هذا الحد! وماذا حدث بعد ذلك؟",
        "opinions|3:1|5|l7": "جعلني أسقي حديقته شهرا كاملا. وبصراحة، كانت تلك نقطة تحول، فقد وقعت في حب النباتات.",
        "opinions|3:1|5|l8": "هل تشعر أحيانا بالحنين إلى تلك الأيام؟",
        "opinions|3:1|5|l9": "كثيرا جدا. كانت الحياة صعبة، لكننا كنا سعداء بالقليل.",
        "opinions|3:1|5|q0": "كيف كان الجد يذهب إلى المدرسة؟",
