        "opinions|4:1|1|p0": "ليتني قضيت وقتا أطول مع جدي.",
        "opinions|4:1|1|p1": "ندمي الوحيد أنني لم أتعلم السباحة أبدا.",
        "opinions|4:1|1|p2": "لو أنني استمعت إلى أمي، لما كنت عالقا في المطر الآن.",
        "opinions|4:1|1|p3": "أدرك الآن أنه كان عليّ أن أختار العلوم بدلا من التجارة.",
