        "opinions|4:1|2|w5": "الجانب المشرق",
        "opinions|4:1|3|p0": "أتطلع حقا إلى رؤية أبناء عمي في فاراناسي في ديوالي هذا العام.",
        "opinions|4:1|3|p1": "بعد سنتين في دبي، شعر بشوق عميق إلى قريته.",
        "opinions|4:1|3|p2": "ستظهر النتائج غدا، لكنني متفائل جدا، إن شاء الله!",
        "opinions|4:1|3|p3": "توقف عن أحلام اليقظة بشأن العطلة وأنه مشروعك أولا.",
        "opinions|4:1|3|p4": "كانت خسارة المباراة محزنة، لكن الجانب المشرق هو أننا تعلمنا الكثير.",
        "opinions|4:1|4|title": "فرصة ثانية في الخامسة والستين",
        "opinions|4:1|4|text": "فينكاتيش في الخامسة والستين من عمره، ويعيش وحده في ميسورو قرب القصر. عندما كان شابا، أتيحت له فرصة لدراسة الموسيقى في تشيناي، لكنه اختار بدلا من ذلك وظيفة آمنة في بنك. ظل لسنوات يقول لنفسه إن ذلك لا يهم، لكن في أعماقه كان هناك دائما ندم صامت. وكان يقول لابنته لاكشمي: «ليتني كنت أشجع.» وفي العام الماضي، وجدت لاكشمي دروسا مسائية في الموسيقى للكبار، وسجلته فيها مفاجأة لعيد ميلاده. في البداية ضحك وقال إن ذلك مجرد تفكير بالتمني، لكنها لم تسمح له بالاستسلام. والآن يتدرب على آلة الفينا كل صباح، ويتطلع إلى أول حفل موسيقي صغير له في مارس. يقول: «لا أستطيع أن أغير الماضي، لكنني سعيد لأنني حصلت أخيرا على فرصة ثانية.»",
        "opinions|4:1|4|q0": "ما الفرصة التي فاتت فينكاتيش في شبابه؟",
        "opinions|4:1|4|q0o0": "دراسة الموسيقى في تشيناي",
