        "opinions|4:1|5|scenario": "رأى عمران للتو نتيجة امتحان القبول. وتلتقي به صديقته كافيثا أمام المكتبة في كالابوراغي.",
        "opinions|4:1|5|l0": "عمران، تبدو منزعجا. هل ظهرت نتيجة امتحان القبول؟",
        "opinions|4:1|5|l1": "نعم. فاتني الحد الأدنى للقبول بأربع درجات فقط. ليتني بدأت الاستعداد مبكرا.",
        "opinions|4:1|5|l2": "أنا آسفة جدا. لكن أربع درجات فرق صغير جدا. من الواضح أنك تعرف موادك.",
        "opinions|4:1|5|l3": "ليتني لم أضيع شهرين كاملين في ألعاب الفيديو!",
        "opinions|4:1|5|l4": "بعد فوات الأوان، يبدو كل شيء واضحا. لا يمكنك أن تغير ذلك الآن، فحاول أن تتجاوزه.",
        "opinions|4:1|5|l5": "أعرف، لكن والدي كانا متفائلين جدا. أشعر أنني خذلتهما.",
        "opinions|4:1|5|l6": "تحدث معهما بصراحة. يمكنك أن تقدم الامتحان مرة أخرى في العام القادم، إنها فرصة ثانية.",
        "opinions|4:1|5|l7": "هذا صحيح. وهذه المرة سأضع جدولا منظما من اليوم الأول.",
        "opinions|4:1|5|l8": "أرأيت؟ هناك جانب مشرق بالفعل. أنا متفائلة بك.",
