        "opinions|5:1|4|title": "صديقان من شيفاموغا",
        "opinions|5:1|4|text": "نشأ أرون وبراكاش في بيتين متجاورين في شيفاموغا، وكانا يتشاركان كل شيء، من مضارب الكريكيت إلى الأسرار. وفي الجامعة، تشاجرا شجارا مريرا عندما ظن براكاش أن أرون أفشى سره للآخرين. لم يكن الأمر إلا سوء فهم، لكن كليهما كان أكثر كبرياء من أن يتصل أولا. ولخمس سنوات لم يتكلما، ورفض أصدقاؤهما أن ينحازوا لأي منهما. أما أم أرون، التي كانت تحب الولدين، فلم تتوقف عن الأمل في أن يتصالحا. وفي زفاف أخت براكاش، وقف الرجلان أخيرا وجها لوجه. قال براكاش: «لقد حملت ضغينة لسبب تافه، فأرجوك سامحني.» فعانقه أرون، ومنذ ذلك اليوم وهما على تواصل كل أسبوع دون انقطاع.",
        "opinions|5:1|4|q0": "لماذا غضب براكاش من أرون؟",
        "opinions|5:1|4|q0o0": "ظن أن أرون أفشى سره للآخرين",
