        "opinions|5:1|5|scenario": "يذهب آكاش لرؤية صديقته من الجامعة سميتا في بيلاغافي. لم تكلمه منذ أسبوع.",
        "opinions|5:1|5|l0": "سميتا، هل يمكننا أن نتحدث لدقيقة؟ أعرف أنك منزعجة مني.",
        "opinions|5:1|5|l1": "منزعجة؟ لقد وعدت بأن تحضر عرضي الراقص، ولم تتصل حتى.",
        "opinions|5:1|5|l2": "معك حق، وأنا آسف حقا. نُقلت جدتي إلى المستشفى في ذلك المساء.",
        "opinions|5:1|5|l3": "يا إلهي! لماذا لم تخبرني؟ ظننت أنك ببساطة لا تهتم.",
        "opinions|5:1|5|l4": "نفدت بطارية هاتفي، وبعد ذلك شعرت بالحرج من أن أشرح. كان سوء فهم سخيفا.",
        "opinions|5:1|5|l5": "ليتك أخبرتني من قبل. لقد حملت ضغينة ضدك أسبوعا كاملا.",
        "opinions|5:1|5|l6": "أفهم ذلك. هل تسامحينني؟ صداقتنا تعني لي الكثير.",
        "opinions|5:1|5|l7": "بالطبع. أنت من أكثر الناس الجديرين بالثقة الذين أعرفهم. كيف حال جدتك الآن؟",
        "opinions|5:1|5|l8": "أفضل بكثير، شكرا. هي في البيت وبدأت تعطي الجميع الأوامر!",
        "opinions|5:1|5|l9": "هذه هي بالضبط. في المرة القادمة، عدني بأن تبقى على تواصل، حتى لو كانت بطارية هاتفك فارغة!",
        "opinions|5:1|5|q0": "لماذا كانت سميتا منزعجة؟",
