        "opinions|6:1|4|title": "نصيحة الجدة",
        "opinions|6:1|4|text": "كانت سنيها من أودوبي في معضلة: فقد قُبلت في كلية للتصميم في أحمد آباد، لكن والديها أرادا أن تدرس قريبا من البيت. شعرت بأنها حائرة بين حلمها وعائلتها، فذهبت إلى جدتها، التي كانت دائما أول من تستشيره. استمعت الجدة بهدوء ثم قالت: «لو كنت مكانك، لما قررت على عجل، فكري في الأمر مليا لبضعة أيام.» وأعطت سنيها أيضا نصيحة صغيرة بشأن تعليقات الأقارب: أن تأخذها بتحفظ. وأضافت الجدة: «قاعدتي العامة بسيطة: اختاري الطريق الذي لن تندمي عليه في الستين.» ثم قدمت اقتراحا: «لماذا لا تُرين والديك موقع الكلية وملف أعمالك؟» أخذت سنيها بنصيحتها، وبعد أن رأى والداها أعمالها، وافقا. واليوم تتصل بجدتها كل يوم أحد وتحكي لها كل شيء عن دروسها.",
        "opinions|6:1|4|q0": "ما المعضلة التي واجهتها سنيها؟",
        "opinions|6:1|4|q0o0": "هل تدرس التصميم في أحمد آباد أم تبقى قرب البيت",
