        "opinions|6:1|5|scenario": "ديباك طالب في السنة الأولى في دارواد، يتصل بابنة عمه الكبرى شاليني ليطلب نصيحتها بشأن زميله في السكن الجامعي.",
        "opinions|6:1|5|l0": "أختي شاليني، هل يمكنني أن أطلب نصيحتك في أمر ما؟ لا أعرف مع من أتحدث غيرك.",
        "opinions|6:1|5|l1": "بالطبع يا ديباك. ما الذي يشغل بالك؟",
        "opinions|6:1|5|l2": "زميلي في السكن يشغل موسيقى صاخبة حتى الثانية صباحا، ولا أستطيع النوم.",
        "opinions|6:1|5|l3": "هذا متعب. هل أخبرته كيف يؤثر ذلك عليك؟",
        "opinions|6:1|5|l4": "ليس تماما. أخشى أن نتشاجر، وعلينا أن نعيش معا طوال العام.",
        "opinions|6:1|5|l5": "لو كنت مكانك، لتحدثت معه بهدوء، في وقت تكونان فيه مرتاحين.",
        "opinions|6:1|5|l6": "هذا اقتراح جيد. لكن ماذا أقول بالضبط؟",
        "opinions|6:1|5|l7": "القاعدة العامة الجيدة هي أن تتحدث عن مشكلتك، لا عن أخطائه. لماذا لا تقترح عليه سماعات الأذن بعد الحادية عشرة؟",
        "opinions|6:1|5|l8": "يبدو هذا عادلا. سأفكر في الأمر مليا وأتحدث معه في عطلة نهاية هذا الأسبوع.",
        "opinions|6:1|5|l9": "جيد. ومن الأفضل ألا تنتظر طويلا، وإلا فستنام في امتحاناتك!",
        "opinions|6:1|5|q0": "ما مشكلة ديباك؟",
