        "society|1:1|1|p1": "ذهبت الصحفية إلى كالابوراغي لتتحدث مع المزارعين بنفسها.",
        "society|1:1|1|p2": "قال مذيع الأخبار إن المباراة ستبث مباشرة الليلة.",
        "society|1:1|1|p3": "لا تعد إرسال أي شائعة قبل أن تتحقق من مصدرها.",
        "society|1:1|1|p4": "تقول افتتاحية اليوم إن مدننا تحتاج إلى نقل عام أفضل.",
        "society|1:1|2|w0": "حادثة",
        "society|1:1|2|w1": "مؤتمر صحفي",
        "society|1:1|2|w2": "جدل",
        "society|1:1|2|w3": "شاهد عيان",
        "society|1:1|2|w4": "تحديث",
        "society|1:1|2|w5": "رد فعل",
        "society|1:1|3|p0": "حسب شاهد عيان، ضغط سائق الحافلة على المكابح فجأة فاصطدمت بالحاجز.",
        "society|1:1|3|p1": "ما زالت الشرطة تحقق في الحادثة التي وقعت قرب محطة القطار.",
        "society|1:1|3|p2": "أثار ما قاله الوزير في المؤتمر الصحفي جدلا كبيرا.",
        "society|1:1|3|p3": "استمر في تحديث الصفحة، فهم ينشرون آخر المستجدات كل عشر دقائق.",
        "society|1:1|3|p4": "ماذا كان رد فعلك الأول عندما سمعت الخبر؟",
        "society|1:1|4|title": "الجسر الذي لم ينهر",
        "society|1:1|4|text": "في إحدى الأمسيات، انتشرت رسالة في أنحاء ميسورو تقول إن الجسر القديم قرب سريرانغاباتنا قد انهار. كاد راهول، وهو طالب جامعي، يعيد إرسالها إلى مجموعة عائلته، لكنه توقف. فتح موقعا إخباريا موثوقا ولم يجد أي عنوان رئيسي من هذا النوع. بل وجد تحديثا قصيرا من صحفية محلية كانت واقفة عند الجسر. وكانت قد تحدثت مع شاهد عيان قال إن جزءا صغيرا فقط من السياج سقط في النهر. لم يصب أحد بأذى، وكان الجسر ما زال مفتوحا. أدرك راهول أن الرسالة مجرد شائعة مبنية على حادثة بسيطة. فنشر الخبر الحقيقي في المجموعة، وطلب من الجميع أن يتحققوا قبل أن يشاركوا أي شيء.",
        "society|1:1|4|q0": "ماذا قالت الرسالة؟",
        "society|1:1|4|q0o0": "أن الجسر القديم قد انهار",
        "society|1:1|4|q0o1": "أن النهر أغرق البلدة",
        "society|1:1|4|q0o2": "أن الكلية مغلقة",
        "society|1:1|4|q0o3": "أن حافلة سقطت في النهر",
        "society|1:1|4|q1": "مع من تحدثت الصحفية؟",
        "society|1:1|4|q1o0": "مع شاهد عيان",
        "society|1:1|4|q1o1": "مع الشرطة",
        "society|1:1|4|q1o2": "مع عائلة راهول",
        "society|1:1|4|q1o3": "مع مذيع أخبار",
        "society|1:1|4|q2": "ماذا فعل راهول في النهاية؟",
        "society|1:1|4|q2o0": "نشر الخبر الحقيقي وطلب من الجميع أن يتحققوا أولا",
        "society|1:1|4|q2o1": "أعاد إرسال الرسالة إلى عائلته",
        "society|1:1|4|q2o2": "ذهب ليرى الجسر بنفسه",
        "society|1:1|4|q2o3": "اتصل بمكتب الجريدة",
        "society|1:1|5|title": "عاصفة الليلة الماضية",
        "society|1:1|5|scenario": "زميلان، ديفيا وعمران، يتحدثان عن أخبار الصباح وهما يشربان القهوة في مكتبهما في بنغالورو.",
        "society|1:1|5|l0": "عمران، هل تابعت الأخبار هذا الصباح؟ هبت عاصفة قوية جدا على بنغالورو الليلة الماضية.",
        "society|1:1|5|l1": "رأيت العنوان الرئيسي، لكنني لم أقرأ الخبر كاملا. ماذا حدث؟",
        "society|1:1|5|l2": "يبدو أن شجرة كبيرة سقطت على حافلة متوقفة في جاياناغار. ولحسن الحظ، كانت الحافلة فارغة.",
        "society|1:1|5|l3": "الحمد لله. هل أصيب أحد؟",
        "society|1:1|5|l4": "لا. قال شاهد عيان للصحفيين إن السائق خرج ليشرب الشاي قبل دقيقة واحدة فقط.",
        "society|1:1|5|l5": "هذا حظ مدهش. وسمعت أيضا شائعة تقول إن المترو توقف. هل هذا صحيح؟",
        "society|1:1|5|l6": "لساعة واحدة فقط. آخر تحديث يقول إن كل الخطوط تعمل بشكل طبيعي من جديد.",
        "society|1:1|5|l7": "بصراحة، رد فعلي الأول هو أن ألوم سوء التخطيط. لماذا لا تُفحص الأشجار القديمة قبل موسم الأمطار؟",
        "society|1:1|5|l8": "هذا بالضبط ما تقوله افتتاحية اليوم. وقد وعدت بلدية المدينة بمسح كل شجرة قديمة.",
        "society|1:1|5|l9": "حسنا، أتمنى أن تفي بوعدها هذه المرة.",
        "society|1:1|5|q0": "أين سقطت الشجرة؟",
