        "society|2:1|0|w0": "هاتف ذكي",
        "society|2:1|0|w1": "تطبيق",
        "society|2:1|0|w2": "يحمّل",
        "society|2:1|0|w3": "إشعار",
        "society|2:1|0|w4": "مساحة التخزين",
        "society|2:1|0|w5": "لقطة شاشة",
        "society|2:1|1|p0": "تعلمت جدتي استخدام الهاتف الذكي في السبعين من عمرها.",
        "society|2:1|1|p1": "لا تحمل التطبيقات إلا من المتجر الرسمي، وليس من روابط عشوائية أبدا.",
        "society|2:1|1|p2": "أوقفت الإشعارات لأنها كانت تشتت انتباهي باستمرار أثناء الدراسة.",
        "society|2:1|1|p3": "هاتفي يتجمد باستمرار لأن مساحة التخزين فيه ممتلئة بفيديوهات قديمة.",
        "society|2:1|1|p4": "خذ لقطة شاشة لصفحة الدفع تحسبا لحدوث أي خطأ.",
        "society|2:1|2|w0": "وسائل التواصل الاجتماعي",
        "society|2:1|2|w1": "متابع",
        "society|2:1|2|w2": "مؤثّر",
        "society|2:1|2|w3": "واسع الانتشار",
        "society|2:1|2|w4": "وقت الشاشة",
        "society|2:1|2|w5": "تعليق",
        "society|2:1|3|p0": "انتشر فيديو الطبخ الخاص بها بسرعة كبيرة، وكسبت عشرة آلاف متابع بين ليلة وضحاها.",
        "society|2:1|3|p1": "يجب أن يكون المؤثر صادقا عندما تدفع له شركة مقابل منشور.",
        "society|2:1|3|p2": "أحاول أن يبقى وقت الشاشة لدي أقل من ساعتين في اليوم.",
        "society|2:1|3|p3": "لا تأخذ التعليقات السيئة بشكل شخصي، فمعظمها يأتي من الغرباء.",
        "society|2:1|3|p4": "وسائل التواصل الاجتماعي تربطنا ببعض، لكنها قد تجعلنا نشعر بالوحدة أيضا.",
        "society|2:1|4|title": "أيام أحد بلا هواتف",
        "society|2:1|4|text": "كل مساء، كانت عائلة شارما في جايبور تجلس في الغرفة نفسها، لكن أحدا لم يكن يتحدث حقا. كان كل فرد مشغولا بهاتفه الذكي، يتصفح وسائل التواصل الاجتماعي أو يشاهد الفيديوهات. وفي إحدى الليالي، تحققت ريا ذات الاثني عشر عاما من وقت الشاشة لديها، فصُدمت حين رأت ست ساعات. فاقترحت قاعدة جديدة: لا هواتف أبدا أيام الأحد، من الفطور حتى العشاء. ضحك والدها في البداية، لأن هاتفه كان دائما مليئا بإشعارات العمل. لكن في أول يوم أحد بلا هواتف، لعبت العائلة الكيرم، وطبخوا معا، بل وزاروا الجد والجدة. وبحلول المساء، لم يفتقد أحد متابعيه أو التعليقات. والآن تضع عائلة شارما هواتفها في سلة كل يوم أحد، وتقول ريا إنه أفضل يوم في الأسبوع.",
        "society|2:1|4|q0": "كم كان وقت الشاشة الذي رأته ريا على هاتفها؟",
        "society|2:1|4|q0o0": "ست ساعات",
        "society|2:1|4|q0o1": "ساعتين",
        "society|2:1|4|q0o2": "اثنتي عشرة ساعة",
        "society|2:1|4|q0o3": "نصف ساعة",
        "society|2:1|4|q1": "ما القاعدة الجديدة؟",
        "society|2:1|4|q1o0": "لا هواتف أيام الأحد من الفطور حتى العشاء",
        "society|2:1|4|q1o1": "لا هواتف بعد العاشرة ليلا",
        "society|2:1|4|q1o2": "ساعة واحدة فقط لوسائل التواصل الاجتماعي يوميا",
        "society|2:1|4|q1o3": "لا هواتف على مائدة العشاء",
        "society|2:1|4|q2": "لماذا ضحك والد ريا في البداية؟",
        "society|2:1|4|q2o0": "لأن هاتفه كان دائما مليئا بإشعارات العمل",
        "society|2:1|4|q2o1": "لأنه كان قد وضع القاعدة نفسها من قبل",
        "society|2:1|4|q2o2": "لأنه لم يكن يملك هاتفا ذكيا",
        "society|2:1|4|q2o3": "لأنه أراد زيارة الجد والجدة",
        "society|2:1|5|title": "هل المشكلة في الهاتف؟",
        "society|2:1|5|scenario": "كيران، طالب جامعي في هوبالي، وعمته لاكشمي، وهي معلمة في مدرسة، يتناقشان: هل تفيد الهواتف الذكية الشباب أم تضرهم؟",
        "society|2:1|5|l0": "كيران، أنت تحدق في تلك الشاشة منذ ساعتين. هل تلاحظ ذلك أصلا؟",
        "society|2:1|5|l1": "أعرف يا عمتي، لكنني لا أضيع وقتي فقط. أنا أشاهد محاضرة عن البرمجة.",
        "society|2:1|5|l2": "معك حق. لكن نصف طلابي يبقون على وسائل التواصل الاجتماعي حتى منتصف الليل، ويأتون إلى الفصل منهكين.",
        "society|2:1|5|l3": "هذا صحيح. بعض التطبيقات مصممة لتجعلك تستمر في التصفح، والإشعارات لا تتوقف أبدا.",
        "society|2:1|5|l4": "إذن هل تظن أن ضرر الهواتف الذكية أكبر من نفعها؟",
        "society|2:1|5|l5": "ليس تماما. في الشهر الماضي دفعت رسوم امتحاني، وحجزت تذكرة قطار، ووجدت عملا بدوام جزئي، وكل ذلك على هاتفي.",
        "society|2:1|5|l6": "لا أستطيع أن أجادل في ذلك. جدتك الآن تتصل بأختها في بونه بمكالمة فيديو كل يوم.",
        "society|2:1|5|l7": "بالضبط. الهاتف مجرد أداة. المشكلة تبدأ عندما لا نستطيع أن نتركه.",
        "society|2:1|5|l8": "إذن إليك هذا التحدي: ضعه في غرفة أخرى وأنت تدرس الليلة.",
        "society|2:1|5|l9": "اتفقنا. لكن عليك أنت أن تتوقفي عن تفقد مجموعة العائلة أثناء العشاء!",
        "society|2:1|5|q0": "ماذا كان كيران يشاهد؟",
