        "society|3:1|0|w0": "زحمة مرور",
        "society|3:1|0|w1": "التنقل اليومي",
        "society|3:1|0|w2": "شقة",
        "society|3:1|0|w3": "جسر علوي",
        "society|3:1|0|w4": "ضاحية",
        "society|3:1|0|w5": "ضجيج",
        "society|3:1|1|p0": "جعلتني زحمة المرور على طريق هوسور أتأخر ساعة مرة أخرى.",
        "society|3:1|1|p1": "تنقلي اليومي يستغرق تسعين دقيقة في كل اتجاه بالحافلة والمترو.",
        "society|3:1|1|p2": "الإيجارات في بنغالورو مرتفعة جدا لدرجة أننا نتشارك شقة واحدة نحن الأربعة.",
        "society|3:1|1|p3": "انتقلنا إلى ضاحية هادئة لنبتعد عن الضجيج.",
        "society|3:1|1|p4": "اختصر الجسر العلوي الجديد طريقي إلى المكتب عشرين دقيقة.",
        "society|3:1|2|w0": "هجرة",
        "society|3:1|2|w1": "مجتمع",
        "society|3:1|2|w2": "مرافق",
        "society|3:1|2|w3": "مجلس القرية",
        "society|3:1|2|w4": "حصاد",
        "society|3:1|2|w5": "هادئ",
        "society|3:1|3|p0": "تركت الهجرة إلى المدن كثيرا من القرى ولا يسكنها إلا كبار السن.",
        "society|3:1|3|p1": "في قريتنا، يساعد المجتمع كله عندما يبني أحد بيتا.",
        "society|3:1|3|p2": "أقرب مستشفى يبعد أربعين كيلومترا، لذلك نحتاج إلى مرافق أفضل هنا.",
        "society|3:1|3|p3": "أصلح مجلس القرية أخيرا الطريق المؤدي إلى موقف الحافلات.",
        "society|3:1|3|p4": "بعد الحصاد، تحتفل القرية كلها بالموسيقى والطعام.",
        "society|3:1|4|title": "بين بيتين",
        "society|3:1|4|text": "قبل خمس سنوات، ترك سانتوش قريته قرب كالابوراغي وانتقل إلى بنغالورو من أجل العمل. وهو يعيش الآن في شقة صغيرة في إحدى الضواحي، ويدفع نصف راتبه إيجارا. يستغرق تنقله ساعتين في اليوم، وزحمة المرور تختبر صبره. ومع ذلك، أعطته المدينة وظيفة جيدة ومرافق لم تكن في قريته قط. وفي الشهر الماضي، عاد إلى بيته لموسم الحصاد، ولاحظ كم كانت الحقول هادئة. لكنه رأى أيضا أن المدرسة ليس فيها إلا معلم واحد، وأن المركز الصحي لا يفتح إلا مرتين في الأسبوع. فتحدث مع مجلس القرية عن بدء دروس في الحاسوب للأطفال. ويعتقد سانتوش أنه إذا حصلت القرى على مرافق جيدة، فستتباطأ الهجرة إلى المدن.",
        "society|3:1|4|q0": "كم من راتبه يدفع سانتوش إيجارا؟",
