        "society|3:1|4|q0o3": "لا شيء منه",
        "society|3:1|4|q1": "ماذا لاحظ سانتوش بشأن مدرسة القرية؟",
        "society|3:1|4|q1o0": "ليس فيها إلا معلم واحد",
