        "society|3:1|4|q1o3": "فيها عدد كبير جدا من الطلاب",
        "society|3:1|4|q2": "ما الذي يعتقد سانتوش أنه سيبطئ الهجرة؟",
        "society|3:1|4|q2o0": "مرافق جيدة في القرى",
