        "society|3:1|4|q2o3": "حصاد أكبر",
        "society|3:1|5|title": "المدينة أم القرية؟",
        "society|3:1|5|scenario": "بوجا، التي نشأت في بنغالورو، وصديقها ماهيش، من قرية قرب مانديا، يتناقشان حول المكان الذي يفضلان العيش فيه.",
        "society|3:1|5|l0": "ماهيش، بصراحة لا أستطيع أن أتخيل العيش في مكان بلا مترو وبلا توصيل طعام في وقت متأخر من الليل.",
        "society|3:1|5|l1": "وأنا لا أستطيع أن أتخيل قضاء ساعتين في زحمة المرور فقط لأصل إلى الجامعة.",
        "society|3:1|5|l2": "نقطة وجيهة. لكن في المدينة، كل شيء قريب: المستشفيات والجامعات والوظائف.",
        "society|3:1|5|l3": "وهذا بالضبط سبب مغادرة كثير من الشباب لقريتنا. لكن لدينا أشياء ليست لديكم.",
        "society|3:1|5|l4": "مثل ماذا؟ غير الهواء النقي، أقصد.",
        "society|3:1|5|l5": "مجتمع حقيقي. عندما مرض أبي، تناوب جيراننا على رعاية حقولنا.",
        "society|3:1|5|l6": "هذا جميل. أنا لا أعرف حتى أسماء الناس في الشقة المجاورة.",
        "society|3:1|5|l7": "بالضبط. في المدينة يحيط بك الناس من كل جانب، ومع ذلك يشعر كثيرون بالوحدة.",
        "society|3:1|5|l8": "إذن ما الذي يجعلك تبقى في القرية؟",
        "society|3:1|5|l9": "إنترنت جيد، ومستشفى حقيقي، وخدمة حافلات لائقة. عندها لن أغادرها أبدا.",
        "society|3:1|5|q0": "ما الذي لا يحبه ماهيش في حياة المدينة؟",
