        "society|4:1|0|w4": "ترتيب",
        "society|4:1|0|w5": "ضغط",
        "society|4:1|1|p0": "مئات الآلاف من الطلاب يقدمون امتحان القبول في كليات الطب كل عام.",
        "society|4:1|1|p1": "المنهج طويل جدا لدرجة أننا بالكاد نجد وقتا للمراجعة.",
        "society|4:1|1|p2": "بعض العائلات تنفق على دروس التقوية أكثر مما تنفق على رسوم المدرسة.",
        "society|4:1|1|p3": "الدرجات مهمة، لكنها لا تحدد مستقبلك كله.",
        "society|4:1|1|p4": "حتى مع ترتيبها المتقدم، شعرت بضغط هائل من أقاربها.",
        "society|4:1|2|w0": "درس عبر الإنترنت",
        "society|4:1|2|w1": "شهادة جامعية",
        "society|4:1|2|w2": "منحة دراسية",
        "society|4:1|2|w3": "مسار دراسي",
        "society|4:1|2|w4": "مهارة",
        "society|4:1|2|w5": "مستشار تربوي",
        "society|4:1|3|p0": "ساعدتنا الدروس عبر الإنترنت أثناء الإغلاق، لكن لا شيء يحل محل الفصل الحقيقي.",
        "society|4:1|3|p1": "هو أول شخص في عائلته يحصل على شهادة جامعية.",
        "society|4:1|3|p2": "تغطي منحة دراسية من الولاية رسوم سكنها الجامعي وكتبها.",
        "society|4:1|3|p3": "اختر مسارك الدراسي لأنك تستمتع به، لا لأن أصدقاءك اختاروه.",
        "society|4:1|3|p4": "قال لي المستشار التربوي إن المهارات العملية مهمة بقدر أهمية الدرجات.",
        "society|4:1|4|title": "طريقها الخاص",
        "society|4:1|4|text": "حصلت نانديني من دافاناغيري على أربعة وتسعين في المئة في امتحانات المرحلة قبل الجامعية، وتوقع الجميع أن تصبح طبيبة. فسجلها والداها في مركز دروس تقوية باهظ استعدادا لامتحان القبول في كليات الطب. لكن نانديني كانت تقضي كل وقت فراغها في تصميم الملصقات والفيديوهات القصيرة لمهرجان كليتها. وازداد الضغط، وصارت تخاف من كل امتحان تجريبي. وأخيرا، قابلت المستشارة التربوية في الكلية، التي استمعت إليها بعناية وساعدتها على استكشاف شهادة جامعية في التصميم. ووجدتا معا منحة دراسية تغطي معظم رسومها. وعندما أرت نانديني والديها ملف أعمالها، ظل أبوها صامتا وقتا طويلا. ثم ابتسم وقال: «إذا كانت هذه مهارتك، فهذا هو طريقك.»",
        "society|4:1|4|q0": "ماذا توقع الجميع أن تصبح نانديني؟",
        "society|4:1|4|q0o0": "طبيبة",
        "society|4:1|4|q0o1": "مصممة",
        "society|4:1|4|q0o2": "معلمة",
