        "society|4:1|4|q2o1": "يجب أن تقدم امتحان القبول مرة أخرى",
        "society|4:1|4|q2o2": "التصميم ليس مهنة حقيقية",
        "society|4:1|4|q2o3": "يجب أن تأخذ سنة إجازة",
        "society|4:1|5|title": "ماذا أدرس؟",
        "society|4:1|5|scenario": "أنهى أديتيا للتو امتحانات المرحلة قبل الجامعية في مانغالورو. ويسأل ابنة عمه الكبرى شروتي، التي تعمل في بونه، عما يجب أن يدرسه بعد ذلك.",
        "society|4:1|5|l0": "إذن يا أديتيا، ظهرت النتائج. هل قررت ماذا ستدرس بعد ذلك؟",
        "society|4:1|5|l1": "ليس تماما. الجميع يقولون الهندسة، لكنني لست متأكدا حتى أنني أحبها.",
        "society|4:1|5|l2": "إذن لا تخترها لمجرد أن الجميع يختارونها. ما المواد التي تستمتع بها فعلا؟",
        "society|4:1|5|l3": "الاقتصاد، بصراحة. وأحب أن أشرح الأشياء، ربما لأنني أدرّس أطفال جيراننا.",
        "society|4:1|5|l4": "هذه مهارة حقيقية. هل فكرت في شهادة جامعية في الاقتصاد، أو حتى في التعليم؟",
        "society|4:1|5|l5": "فكرت، لكن أبي يخشى ألا تكون هناك وظائف جيدة. ويظل يقارنني بابن عائلة راو الذي التحق بالمعهد الهندي للتكنولوجيا.",
        "society|4:1|5|l6": "هذا النوع من الضغط شائع، لكن سوق العمل يتغير بسرعة. مهارات التواصل وحل المشكلات مطلوبة في كل مكان.",
        "society|4:1|5|l7": "وهل ستفيدني الدورات عبر الإنترنت أيضا؟",
        "society|4:1|5|l8": "بالتأكيد. خذ دورة قصيرة في تحليل البيانات إلى جانب دراستك الجامعية، واحجز جلسة مع المستشار التربوي في كليتك.",
        "society|4:1|5|l9": "فكرة جيدة. ربما إذا سمعها أبي من مستشار، فسيأخذها بجدية أكبر.",
        "society|4:1|5|q0": "ما المادة التي يستمتع بها أديتيا حقا؟",
